/* 全库分片 43/43，共 370 首（chinese-gushiwen / chinese-poetry）*/
window.QUAN_KU_PART_42 = [
  {"t":"十三煞・穿长街蓦短衢，上歌台入酒楼。忙呼乐探差祗候：众人暇日邀官","p":"","d":"元代","a":"无名氏","c":["舍，与你几贯青蚨唤粉头。", "休辞生受，请个有声名旦色，迭标垛娇羞。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"十一・待呼小卿不姓苏，待唤月仙不姓周。你桂英性子实村纣，施施所事","p":"","d":"元代","a":"无名氏","c":["皆无礼，似盼盼多应也姓刘。", "满饮阑门酒，似线牵傀儡，粉做骷髅。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"九・有玉箫不会品，有银筝不会ㄐ，查沙着一对生姜手。眼М间准备钳肴","p":"","d":"元代","a":"无名氏","c":["馔，酩子里安排搠按酒。", "立不住腔腔嗽，新清来的板齿，恰刷起黄头。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"八・〔青哥儿〕怎地弹，〔白鹤子〕怎地讴，燥躯老第四如何纽。恣胸怀","p":"","d":"元代","a":"无名氏","c":["休想我一缕儿顽涎退，白珠玉别得他浑身拙汗流。", "倒敢是十分丑。", "匾扑沙拐孤撇尺，光笃鹿瓠子髑髅。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"四・忍不得腹内饥，揩不得脸上羞，休猜做饱谙世事慵开口。俺座间虽无","p":"","d":"元代","a":"无名氏","c":["百宝妆腰带，您席上怎能够真珠络臂鞲。", "闻不得腥臊臭，半年两番小产，一日九遍昏兜。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"三・〔江儿里水〕唱得生，〔小姑儿〕听记得熟。入席来把不到三巡酒，","p":"","d":"元代","a":"无名氏","c":["索怯薛侧脚安排趄，要赏钱连声不住口。", "没一盏茶时候，道有教坊散乐，拘刷烟月班头。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"二・提控有小朱，权司是老刘，更有那些随从村禽兽。唬得烟迷了苏小小","p":"","d":"元代","a":"无名氏","c":["夜月莺花市，惊得云锁了许盼盼春风燕子楼。", "慌煞俺曹娥秀，抬乐器眩了眼脑，觑幅子叫破咽候。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"一・上瓦里封了门，下瓦里觅了舟。他道眼睁睁见死不救。比怕阎罗王罪","p":"","d":"元代","a":"无名氏","c":["恶多些人气，似征李志甫巡军少个犯由。", "恰便似遭遗漏，小王抗着毡缕，小李不放泥头。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・老卜儿藉不得板一地走，狠撅丁夹着锣则顾得走。也不是沿村串疃钻","p":"","d":"元代","a":"无名氏","c":["山兽，则是喑气吞声丧家狗。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"逍遥乐・我从来眼硬，不由人对景伤情，一哭一个放声。想当初又不曾约","p":"","d":"元代","a":"无名氏","c":["定离情，常言道：乐极悲生。", "伴吹箫玉人不见影，洞房中冷冷清清。", "空闲了罗帏锦帐，绣枕鸳衾，翠榻银屏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"金菊香・虚飘飘幽梦盼着难成，静悄悄孤眠睡着又醒，瘦怯怯身躯温着又","p":"","d":"元代","a":"无名氏","c":["夜迢迢捱不到天明，料应来司天台上多打二三更。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梧叶儿・问明月浑无语，唤梅花不肯应，长叹倚空庭。何处品青鸾管？谁","p":"","d":"元代","a":"无名氏","c":["家奏彩凤笙？都吹出断肠声，不管离人怕听。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醋葫芦・几番上危楼将曲槛凭，不承望愁先在楼上等。望不见娇滴滴天上","p":"","d":"元代","a":"无名氏","c":["董双成，泻长空苍苍烟树暝。", "残霞掩映，江上数峰青。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・论文学不什么明，论江湖不甚么省。则我这粗贱才堪配玉聘婷，我将","p":"","d":"元代","a":"无名氏","c":["这女娘行恩情在等秤上称。", "称了时和咱比并，十分情重全无有半星儿轻。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"后庭花・丽春园曾惯经，教坊司也惯行。人都说金钗客无缘分，我只道玉","p":"","d":"元代","a":"无名氏","c":["天仙有眼睛。", "他将我好看承，我将他心窝里相敬。", "扯嗉儿不手生，跄跪儿不腿疼。", "常将笑脸儿迎，勤把热气儿腾。", "活观音额上顶，夜明珠掌上擎，夜明珠掌上擎。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"青歌儿・呀，他是我今生、今生性命，那世、那世魂灵。一去教人不快情。","p":"","d":"元代","a":"无名氏","c":["遮莫有锦阵花营，酒友诗朋，象板银筝，歌舞吹笙。", "花朵人儿将玉杯擎，我只是无情兴。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"柳叶儿・呀，我这里担着寂寞，不知你在那搭儿里泪眼盈盈，离恨天高越","p":"","d":"元代","a":"无名氏","c":["显的人孤另。", "则我这相思病。", "诉与天听，连天也瘦的来伶仃。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾声・他忧时为我忧，我病时因他病。我为了他害杀了有甚么不相应。有","p":"","d":"元代","a":"无名氏","c":["一日再团圆，画堂春自生。", "紧紧的将他搂定，我将这满怀愁尽向他耳朵儿里倾。", "喜相逢并头花下友，天配偶两娇羞。", "一对儿冤家合欠，还今生谐老鸳俦。", "意相投似漆如胶，契相合万种绸缪。", "画堂前满斟香糯酒，喜孜孜共饮金瓯。", "则吃的天边明月转，楼上换更筹。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"字字锦南・瑶阶羡晚游，闲行携素手。金莲款款移，细柳腰肢瘦。看花楼","p":"","d":"元代","a":"无名氏","c":["抚景偏优，笑吟吟转过见新月一钩。", "休辜负好景，香醪再酬。", "低低悄语私情授，向兰房锦鸾早俦。", "慢松丁香细钮，香散绣帏。", "娇滴滴温柔玉体，非宿世怎生消受。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醋葫芦北・温柔谁并肩，风流为世首。弹弦品竹最精熟，吟诗作赋时下有。","p":"","d":"元代","a":"无名氏","c":["一团儿玲珑剔透，天生的秀气，他两个总全周。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醋葫芦北・姊妹每一个所事全，一个件件周。好似那二乔镜像影儿留，占","p":"","d":"元代","a":"无名氏","c":["梨园委实无对手。", "常想着欢娱时候，我和他契相合情相好意相投。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"皂罗袍南・美满恩深情厚，愿百年谐老，共守白头。相逢谁似恁风流，终","p":"","d":"元代","a":"无名氏","c":["朝弦管笙歌奏。", "池亭东畔，湖山西首，金怀慢举佳肴广，有蓬莱仙境无如右。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"逍遥乐・非是把盟言辜负，多应是身事牵萦，致令的佳期间阻。抛撇下红","p":"","d":"元代","a":"无名氏","c":["粉娇姝，自别来消息全无。", "怎能够萧娘一纸书，多应是水底沉鱼。", "好教我难捱白昼，最怕黄昏，几遍嗟吁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"金菊香・无奈这逼人富贵太拘束，拈脂光阴忒迅速，一树红芳替他难做主。","p":"","d":"元代","a":"无名氏","c":["等闲间减翠消绿，却教我感时抚景怎支吾。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・我也曾絮叨叨讲口舌，实丕丕倾肺腑。下了些调风弄月死工夫，想章","p":"","d":"元代","a":"无名氏","c":["台是一条直路途。", "被谁拦住？莫不是姻缘簿上把我姓名除。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・我和他受孤凄有业缘，永团圆无分福。断弦破镜怎接续？枉自求神与","p":"","d":"元代","a":"无名氏","c":["问卜。", "莫逃天数，料孤辰寡宿单照我身躯。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・我似那鸳鸯怕自飞，我似那鸾鹤该并舞。由来天性怎生拂。我和他久","p":"","d":"元代","a":"无名氏","c":["交欢乍知离别苦。", "百无是处，眼睁睁伶俐变糊突。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梧叶儿・相思病何时退？睡魔神镇日侮，害的我忒荼毒。刁骚了双蓬鬓，","p":"","d":"元代","a":"无名氏","c":["扑簌的两泪珠，缑山岭恁崎岖，隔断了吹箫伴侣。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"后庭花・这些时捻霜毫懒写摸，理冰弦乖律吕。倦开眼亲黄卷。怎舒情倒","p":"","d":"元代","a":"无名氏","c":["玉壶。", "天气更萧肃，你便是铁石人也耽不去。", "妒黄花金色铺，泣丹枫血泪枯。", "望空江练一幅，对遥山青几矗。", "别离怀容易触，别离人生怕睹。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"青哥儿・呀，自别了风流风流人物，终须是有日有日欢娱，对付我心肠谅","p":"","d":"元代","a":"无名氏","c":["不殊。", "且看他俊俏规模，香软肌肤，巧妙妆束，耍笑喧呼。", "行行步步紧随逐，谩把流年度。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"浪来里煞・杜少陵秋兴诗，欧阳子秋声赋。都对不着我的题目，大都来一","p":"","d":"元代","a":"无名氏","c":["见他万事足。", "别无甚忧虑，成就了碧桃花下凤鸾雏。", "佳遇记当年宴青楼初见影，兜的就飞去了俏魂灵。", "只疑是玉天仙空中谪降，又猜做美嫦娥月里相迎。", "猛可里翠屏帏密转秋波，没揣的绿纱窗暗恼春情。", "感承他会佳期预先花下等，成就了片霎儿前程。", "也不让人间秦弄玉，天上许飞琼。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"金菊香・往常时追欢谢馆可曾经，今日个买笑章台惯索行。几番家静守幽","p":"","d":"元代","a":"无名氏","c":["居深自省，天与聘婷，刚道喜又还惊。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醋葫芦・喜呵，好姻缘成的未深；惊呵，歹离别来的最灵。都只为阻蓝桥","p":"","d":"元代","a":"无名氏","c":["如间阻百重城，咫尺间地北天南分凤颈。", "不能够相偎相并，把一场好恩情分付在短长亭。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・我为他枕边厢洒了泪痕，他为我被窝中劳了些梦境。谁承望胶漆的恩","p":"","d":"元代","a":"无名氏","c":["爱半途坑，几回家望断孤鸿楼外影。", "都只是天高云淡，闪的个美幽欢生做了断肠声。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・我将他并不曾冷气呵，他见我常时把热脸儿迎。他也曾画堂春排宴请","p":"","d":"元代","a":"无名氏","c":["高朋，听了些一曲新腔音调整。", "助了些诗人高兴，俺也曾厌厌夜饮到更深。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・想着他和明月品着玉萧，唱阳春奏着锦筝。想着他纤纤素手进瑶觥，","p":"","d":"元代","a":"无名氏","c":["他也曾醉舞霓裳娇态逞。", "出落的十分端正，他比那海棠花睡起更轻盈。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・他也曾斗娇姿花外游，他也曾叙幽情月底行。他和我唱新词曾把字儿","p":"","d":"元代","a":"无名氏","c":["评，我与他立尽花梢明月影。", "遂了这风流佳庆，曾说的楼头北斗柄儿横。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"逍遥乐・自从钗分金凤，止不过数日程途，阻隔着云山万重。走红尘萍梗","p":"","d":"元代","a":"无名氏","c":["飘蓬，叹青春湖海西东。", "几番家恼人愁越重，一声声风送帘栊。", "猿啼峻岭，雁过南楼，鹤唳高松。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"金菊香・瑶琴闲挂锦囊中，宝剑慵弹锦袋中，翠衾倦铺锦帐空。砚匣尘蒙，","p":"","d":"元代","a":"无名氏","c":["都是一般潇洒月明中。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梧叶儿・愁填满东洋海，闷弥高太华峰，愁和闷锁眉丛。这些时笔砚无心","p":"","d":"元代","a":"无名氏","c":["近，经史不待攻。", "我这里怨天公，几时得凄凉卷终。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"后庭花・想则想蹴金莲三寸弓，启樱桃半点红。想则想整酥体一团玉，露","p":"","d":"元代","a":"无名氏","c":["春纤十指葱。", "透酥胸，麝兰香送。", "傍妆台整玉容，列华筵捧玉钟。", "按红牙思转浓，拔银筝兴不穷。", "望瑶池云乱封，盼青鸾信不通。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"柳叶儿・呀，想着俺多娇情重，更那堪剔透玲珑。路迢迢雾锁桃源洞，团","p":"","d":"元代","a":"无名氏","c":["圆梦总成空，楚阳台云雨无踪。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・越思量越惨凄，转伤悲转疼痛，几宵魂梦与伊同。往常时醉归来画堂","p":"","d":"元代","a":"无名氏","c":["红袖拥，到如今有谁人陪奉，都做了断肠词权写付云鸿。", "夜深沉画堂门半掩，正明月转雕檐。", "响珊珊竹声幽院，颤巍巍花影重檐。", "酒才醒幽思沉沉，漏初分凉夜厌厌。", "早秋天万般愁闷添，更凄凉风景相兼。", "旧愁深肺腑，新恨上眉尖。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"逍遥乐・玉容娇艳，记当时柳画宫眉，花明笑靥。尽欢娱无甚拘钳，似于","p":"","d":"元代","a":"无名氏","c":["飞燕燕鹣鹣。", "微利驱人成弃闪，走天涯旅邸顿腌。", "肠如线结，心如锥剜，肉似刀签。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"金菊香・早鸦灵鹊不须占，蓍草金钱徒自检，灯花喜蛛都是诌。无准信龟","p":"","d":"元代","a":"无名氏","c":["卦神签，更那堪半衾幽梦睡初タ。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・凤凰翅活不剌手中ㄎ，鸳鸯弹圆滴滴石上掂，翡翠羽恶支沙泥内染。","p":"","d":"元代","a":"无名氏","c":["连理枝雪虐霜严，好花开处雨纤纤。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醋葫芦・彩云深白雁稀，碧波寒锦鲜潜。素书银字不曾瞻，隔云山万重天","p":"","d":"元代","a":"无名氏","c":["路险。", "旧恩情不堪追念，都做了镜中花影水中盐。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・择兔毫斑管拈，洒鸾笺香墨染。写平安端肃更谦谦，诉离怀半缄情越","p":"","d":"元代","a":"无名氏","c":["从别后绝无瑕玷，封皮儿上两行情泪带愁粘。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"越调・斗鹌鹑元宵","p":"","d":"元代","a":"无名氏","c":["圣主宽仁，尧民尽喜。", "一统华夷，诸邦进礼。", "雨顺风调，时丰岁丽。", "元夜值，风景奇。", "闹穰穰的迓鼓喧天，明晃晃的金莲遍地。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"紫花儿序・香馥馥绮罗还往，密匝匝车马喧阗，光灼灼灯月交辉。满街上","p":"","d":"元代","a":"无名氏","c":["王孙公子，相携着越女吴姬。", "偏宜，凤烛高张照珠履。", "果然豪贵，只疑是洞府神仙，闲游在阆苑瑶池。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"小桃花・归来梅影小窗移，兰麝香风细。翠袖琼簪两行立，捧金杯，绛绡","p":"","d":"元代","a":"无名氏","c":["楼上笙歌沸。", "冰轮表里，通宵不寐，是爱月夜眠迟。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"金蕉叶・拚沉醉频斟绿蚁，恣赏玩朱帘挂起。歌舞动欢声笑喜，一任铜壶","p":"","d":"元代","a":"无名氏","c":["漏滴。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・须将酩酊酬佳致，乐意开怀庆喜。但愿岁岁赏元宵，则这的是人生落","p":"","d":"元代","a":"无名氏","c":["得的。", "绿柳凋残，黄花放彻。", "塞雁声悲，寒蛩韵切。", "旧恨千般，新愁万叠。", "正美满，忍间别。", "雨歇云收，花残月缺。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"紫花儿序・摘楞的瑶琴弦断，不通的井坠银瓶，吉丁的碧玉簪折。音书难","p":"","d":"元代","a":"无名氏","c":["寄，去路遥赊。", "伤嗟，目断云山千万叠。", "最苦是离别，鸳被空舒，凤枕虚设。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"金蕉叶・那的是情牵恨惹，那的是肠荒腹热。怕的是纱窗外风飘败叶，又","p":"","d":"元代","a":"无名氏","c":["听的铁马儿丁当韵切。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"调笑令・把眉峰暗结，最苦是离别，不烦恼除非心似铁。冷清清捱落西楼","p":"","d":"元代","a":"无名氏","c":["月，又听得戍楼上画角呜噎。", "奏《梅花》数声砧韵切，业心肠越不宁贴。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"秃厮儿・正欢悦谁知间别，才美满又早离别。俺两个云期雨约难弃舍，似","p":"","d":"元代","a":"无名氏","c":["团圆一轮月，被云遮。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"圣药王・好教我愁万结，恨万叠，满怀愁闷对谁说。成间别，时运拙，气","p":"","d":"元代","a":"无名氏","c":["长吁多似篆烟斜，和绛蜡也啼血。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"鬼三台・也是我前生业，今世里填还彻，一寸愁肠千万结。想啼痕一点点","p":"","d":"元代","a":"无名氏","c":["尽成血，越教人哽噎。", "本待要宁宁帖帖刚睡些，怎禁那啾啾唧唧蛩韵切。", "觉来时宝鼎烟消，铜壶漏绝。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"紫花儿序・惊好梦几声儿寒雁，伴人愁的一点孤灯，照离情半窗残月。临","p":"","d":"元代","a":"无名氏","c":["歧执手，不忍分别。", "只待稳步蟾宫将仙桂折，到如今暮秋时节。", "他只待金榜名标，那里问玉箫声绝。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・受凄惶甚识分明夜，把捱过的凄凉记者。来时节一句句向枕头儿上言，","p":"","d":"元代","a":"无名氏","c":["一星星向被窝儿里说。", "半世飘蓬，闲茶浪洒。", "十载追陪，狂朋怪友。", "倚翠偎红，眠花卧柳。", "怪胆儿聪，耍性儿柔。", "成会了心厮爱夫妻，情厮当配偶。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"紫花儿序・受用春内谢馆，晓日章台，夜月秦楼。向红裙中插手，锦被里","p":"","d":"元代","a":"无名氏","c":["舒头。", "风流，不许傍人下钓钩。", "燕侣莺俦，百匹酬歌，红锦缠头。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"金蕉叶・寨儿里相知是有，一见咱望风举手。若论着点砌排科惯熟，敢教","p":"","d":"元代","a":"无名氏","c":["那罢剪嘴姨夫闭口。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"调笑令・声名儿岁久，急难收。则恐怕扶侍冤家不到头，风月脚到处须成","p":"","d":"元代","a":"无名氏","c":["誓不曾落人机彀，搬的他燃香剪发百事有。", "虚心冷气，使尽刚柔。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"圣药王・春事休，夏当游，向芰荷香里泛兰舟。到中秋，月色幽，醉醺醺","p":"","d":"元代","a":"无名氏","c":["无日不登楼，兀剌抵多少风雨替花愁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・花阴柳影，霎时驰骤，急回首三旬左右。罢却爱月惜花心，闲着题诗","p":"","d":"元代","a":"无名氏","c":["画眉手。", "（媚）（媚）姿姿，淹淹润润。", "袅袅婷婷，风风韵韵。", "脸衬朝霞，指如嫩笋。", "一搦腰，六幅裙，万种妖娆，千般可人。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"紫花儿序・曲弯弯蛾眉扫黛，慢松松凤髻高盘，高耸耸蝉鬓堆云。一团儿","p":"","d":"元代","a":"无名氏","c":["旖旎，百倍儿精神。", "超群，越女吴姬怎生衬。", "席上殷勤，百媚庞儿，端的一笑风生。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"秃厮儿・瘦怯怯金莲窄稳，娇滴滴皓齿朱唇，肌如美玉无玷损。但见了，","p":"","d":"元代","a":"无名氏","c":["总消魂，绝伦。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"圣药王・酒半醺，更漏分，画堂银烛照黄昏。枕上恩，被底亲，丁香笑吐","p":"","d":"元代","a":"无名氏","c":["兰麝喷，灯下看佳人。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・好姻缘休到别离恨，只恐怕两下里魂牵梦引。我罗衫衤肯儿宽，你唐","p":"","d":"元代","a":"无名氏","c":["裙带儿尽。", "雪艳霜姿，香肌玉软。", "杏脸红娇，桃腮粉浅。", "金凤斜簪，云鬟半偏。", "插玉梳，贴翠钿。", "舞态轻盈，歌喉宛转。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"紫花儿序・他有苏卿般才貌，我学双渐真诚，望博个美满姻缘。俳优体样，","p":"","d":"元代","a":"无名氏","c":["乐府梨园。", "天然，不若如桃源洞里仙。", "可爱堪怜、一搦腰肢，半折金莲。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"小桃红・初出兰堂立樽前，似月里嫦娥现，一撮精神胜飞燕。正当年，柳","p":"","d":"元代","a":"无名氏","c":["眉星眼芙蓉面。", "绛衣缥缈，麝兰琼树，花里遇神仙。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"天净沙・初相逢恨惹情牵，间深里都受熬煎，各办着心真意坚。有时得便，","p":"","d":"元代","a":"无名氏","c":["赴佳期月底星前。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・狠毒娘间阻得难相见，统镘的姨夫恋缠。我为甚着探脚儿勤，只恐怕","p":"","d":"元代","a":"无名氏","c":["离别路儿远。", "雨意云情，十朝五朝。", "霜艳天姿，千娇万娇。", "凤髻浓梳，蛾眉淡扫。", "樱桃口，杨柳腰。", "玉笋纤纤，金莲小小。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"紫花儿序・歌骊珠一串，舞端雪千回，无福也难消。超群旖旎，出格妖娆。","p":"","d":"元代","a":"无名氏","c":["风流，一笑千金价不高。", "世间绝妙，特意厚情深，引得人梦断魂劳。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"秃厮儿・儿中眉尖眼角，寨儿中口强心乔，谢琼姬不嫌王子高。同跨凤，","p":"","d":"元代","a":"无名氏","c":["宴蟠桃，吹箫。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"小桃红・倚阑无语忆多才，往事今何在，玉体厌厌为谁害，瘦形骸，今春","p":"","d":"元代","a":"无名氏","c":["更比前春赛。", "雕阑玉砌，绿窗朱户，深院锁苍苔。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉扶归・松却香罗带，慵整短金钗，无语无言闷答孩。不厌倦衫儿窄，几","p":"","d":"元代","a":"无名氏","c":["度将龟儿卦买，何日佳期再。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"天净沙・也是咱运拙时乖，致令得雨杳云埋，侧脚里相知不该。胡喧乱讲，","p":"","d":"元代","a":"无名氏","c":["纸糊锹怎撅得倒阳台。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・把一片偷香窃玉心宁耐，喑气吞声慢捱。怕甚风月闷愁乡，烟波是非","p":"","d":"元代","a":"无名氏","c":["妓好睡莫不是陈抟的姨姨，庄周的妹妹，宰予的家属，谢安的亲戚。", "华胥梦里姻缘，邯郸道上配偶。", "两件儿，试问你，可甚爱月迟眠，惜花早起。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"紫花儿・西厢底莺莺立睡，茶船上小卿着昏，东墙下秀英如痴。真乃是弃","p":"","d":"元代","a":"无名氏","c":["生就死，便休想废寝忘食。", "休题，除睡人间总不知。", "正是困人天气，啼杀流莺，叫死晨鸡。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・推着倒鸾交凤友，倩人扶燕侣莺俦，合着眼蝶使蜂媒。绣衾未展，玉","p":"","d":"元代","a":"无名氏","c":["山先颓。", "其实，倒枕着床是你记得的。", "胡突了一世，恰便似楚阳台半死的梅香，兰昌宫殉葬的奴婢。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"小桃红・莫不是离魂倩女醉杨妃，是个有觉的平康妓。难道娇娥不出气，","p":"","d":"元代","a":"无名氏","c":["懵憧的最怜伊。", "颠鸾倒凤先及第，直压的珊瑚枕低。", "黄金钏碎，平地一声雷。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"圣药王・子弟每，做伴的，安排着好梦做夫妻。你也休问谁，我也不答你。","p":"","d":"元代","a":"无名氏","c":["陷人坑上被儿里，直挺着块望夫石。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・对苍天曾说牙疼誓，直睡到红日三竿未起。若要战退睡魔王，差三千","p":"","d":"元代","a":"无名氏","c":["个追魂大力鬼。", "离恨送玉傅香，撩蜂拨蝎。", "病枕愁衾，寻毒觅螫。", "掷闷果的心劳，画颦眉的手拙。", "恨岳高，泪海竭。", "难凭信鹊验龟灵。", "无定准鱼封雁帖。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"紫花儿序・莫不是金华字减消了官诰，芙容翠低小了云冠，鲛绡盖乍窄了","p":"","d":"元代","a":"无名氏","c":["香车？闷弓儿常拽，愁窖儿频掘。", "伤嗟，一纳头相思害不彻。", "赤紧的俏心儿先热，无倒断暮雨朝云，无拘束粉祟胭邪。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"小桃红・锦笺和泪寄离别，好事成抛撇。恨杀梅香性偏劣，闭喉舌，今翻","p":"","d":"元代","a":"无名氏","c":["瘦损罗裙褶。", "他把那游蜂儿蜜劫，粉蝶儿香卸，生撅的风月担儿折。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"调笑令・我恰待睡些，不宁贴，熏金炉引梦赊。破题儿告一纸相思赦，楚","p":"","d":"元代","a":"无名氏","c":["巫娥不顺关截。", "恰相逢陡恁般厮间别，望阳关永远山叠。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"秃厮儿・啼杜宇枝头泪血，惊庄周枕上残蝶，追魂数声檐外铁。这凄凉几","p":"","d":"元代","a":"无名氏","c":["时绝，堪嗟。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"圣药王・伴着这灯影昏，月影斜，隔纱窗花影乱重叠。钟韵凄，鼓韵切，","p":"","d":"元代","a":"无名氏","c":["听楼头角韵尚悠噎，似这般离恨怎拦遮。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"麻郎儿・病沉也相思赌忄敝，愁深也沈约搬舌。薄设设青铜镜缺，颤巍巍","p":"","d":"元代","a":"无名氏","c":["连理枝截。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"络丝娘・心头事十强九怯，眉尖恨千结万结。盼的团圆向明月，空立遍露","p":"","d":"元代","a":"无名氏","c":["零花谢。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾声・闷恹恹好似如年夜，常记的相思那些。题起那眉尖恨恰舒开，心儿","p":"","d":"元代","a":"无名氏","c":["疼又到也。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・新水令","p":"","d":"元代","a":"无名氏","c":["大明开放九重天，拜紫宸玉楼金殿。", "红摇银烛影，香袅御炉烟。", "奏凤管冰弦，唱大曲梨园。", "列文武官员，降玉府神仙，齐贺太平年。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庆东原・遣奉使传丹诏，赈饿贫审滞冤，黜贪邪访民瘼巡行遍。陛下恩极","p":"","d":"元代","a":"无名氏","c":["四边，祥开万年，和应三元。", "选人物治朝纲，取进士登科选。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"雁儿落得胜令・朝廷德化宣，台察清风宪。都堂有政声，枢府无征战。四","p":"","d":"元代","a":"无名氏","c":["海永安然，诸邦尽朝献。", "武将每黄阁麒麟上，宰相每青霄日月边。", "仰洪福齐天，无东面征西夷怨。", "君贤臣贤，庆吾皇泰定年。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"鸳鸯煞・万万载户口增田畴辟民归善，民归善省刑罚薄税敛差徭免差徭免，","p":"","d":"元代","a":"无名氏","c":["日月同明，日月同明嵩岳齐肩。", "唱道、唱道虎据中原，虎据中原龙飞九天，龙飞九天雨顺风调合天意随人愿。", "随人愿照百二山川，照百二山川一点金星瑞云里现。", "闲争夺鼎沸了丽春园，欠排场不堪久恋。", "时间相敬爱，端的怎团圆？白没事教人笑惹人怨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"驻马听・锦阵里争先，紧卷旗幡不再展；花营中挑战，劳拴意马与心猿。","p":"","d":"元代","a":"无名氏","c":["降书执写纳君前，唇枪舌剑难施展。", "参破脱空禅，早抽头索甚他人劝。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"天仙子・从今后，识破野狐涎。红粉无情，灾星不现。村酒酽野花浓，再","p":"","d":"元代","a":"无名氏","c":["不粘拈。", "当时话儿无应显？好事天悭。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・料应也不得为姻眷，有了神前咒怨。为甚脚儿稀，尺紧得阳台路儿远。","p":"","d":"元代","a":"无名氏","c":["搅闲风吹散楚台云，天对付满怀愁闷。", "您那里欢娱嫌夜短，俺寂寞恨长更。", "恰似线断风筝，绝鱼雁杳音信。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"驻马听・多绪多情，病身躯憔悴损；闲愁闲闷，将柳带结同心。瘦岩岩宽","p":"","d":"元代","a":"无名氏","c":["褪了绛绡裙，羞答答恐怕他邻姬问。", "若道伤春，今年更比年时甚。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・早是我愁怀闷哽，更那堪四扇帏屏。遣人愁添人恨，无端怨煞丹青。","p":"","d":"元代","a":"无名氏","c":["画得来双双厮配定，做得伤情对景。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"天仙子・一扇儿画着双通叔和苏氏到豫章城，一扇儿是司马文君。一扇儿","p":"","d":"元代","a":"无名氏","c":["是王魁桂英。", "画的来厮顾盼厮温存，比各青春。", "这一扇儿比他每情更深，是君瑞莺莺。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"夜行船・又引起往前风月胆，今番做得尴尬。且休说久远当来，奈何时暂，","p":"","d":"元代","a":"无名氏","c":["这些时陡羞惨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"离亭宴煞・你休起风波剁断渔舟缆，得团圆摔破青铜鉴。冤家行再三，再","p":"","d":"元代","a":"无名氏","c":["三嘱付勤相探。", "常将好事贪，却休教花星暗，万一问休将人倒赚。", "眼М了可憎才，心疼煞志诚俺。", "凤凰台上忆吹箫，似钱塘梦魂初觉。", "花月约，凤鸾交。", "半世疏狂，总做了一场懊。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"驻马听・黄诏奢豪，桑木剑熬乏古定刀；双郎穷薄，纸糊锹掘了点钢锹。","p":"","d":"元代","a":"无名氏","c":["怕不待争锋取债恋多娇，又索书名画字寻人保。", "枉徒劳，供钱买笑教人笑。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"落梅风・姨夫闹，咱便烧，君子不夺人之好。他揽定磨杆儿夸俏，推不动","p":"","d":"元代","a":"无名氏","c":["磨杆上自吊。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"步步娇・积趱下三十两通行鸦青钞，买取个大笠子粗麻罩。妆甚腰，眼落","p":"","d":"元代","a":"无名氏","c":["处和他契丹交。", "虽是不风骚，不到得着圈套。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"离亭宴带歇指煞・佳人有意郎君俏，郎君没钞莺花恼。如今等惜花人弄巧，","p":"","d":"元代","a":"无名氏","c":["止不过美话儿排，虚科儿套，实心儿少。", "想着月下情，星前约，是则是花木瓜儿看好。", "李亚仙负心疾，郑元和下番早。", "暮春天气正愁人，对东风乱红成阵。", "愁白昼，恨黄昏。", "旧恨新愁，都在这时分。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"夜行船・望断归鸿共锦鳞，不传织锦回文。多病多躯，怯春方寸，谩赢得","p":"","d":"元代","a":"无名氏","c":["沈腰潘鬓。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"步步娇・劣性儿从前人难奔，何下手咱行顺。谩着外人，忙里偷闲厮温存。","p":"","d":"元代","a":"无名氏","c":["想着那些儿恩，教俺几世儿填还尽。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"拨不断・苦伤神，谩销魂，瘦来生怕旁人问。司马空怜多病身，文君不寄","p":"","d":"元代","a":"无名氏","c":["平安信，可知道一亲一近。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"步步娇・宝髻高盘堆云雾，钗插荆山玉。离洛浦，天赐仙姿出尘俗。更通","p":"","d":"元代","a":"无名氏","c":["疏，无半点儿包弹处。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"拨不断・美妻夫，笑相呼。珠围翠绕今年福，红粉殷勤捧绿醑。桃花扇底","p":"","d":"元代","a":"无名氏","c":["歌《金缕》，不堪消喻。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"离亭宴煞・直吃到落花风散笙歌住，朦胧月转西楼去。舒翡翠被儿中眠，","p":"","d":"元代","a":"无名氏","c":["鸳鸯帐儿里宿。", "思情碧梧天静暮云收，入罗衣晚风凉透。", "屏开闲孔雀，帘簌控金钩。", "懒上危楼，书慵寄雁来候。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"驻马听・鬼病淹留，白发相如岂耐愁。泪痕依旧，青衫司马不禁秋。锦橙","p":"","d":"元代","a":"无名氏","c":["香绽露金柔，丹枫叶落霜红皱。", "俺倦凝眸，别离咫尺重阳又。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"得胜令・呀，思量来端的没来由，和您娘无事做敌头。不是这掷果的潘安","p":"","d":"元代","a":"无名氏","c":["俏，都则为当垆的卓氏羞。", "休忧，有日还成就；娇柔，忽的心上有。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"甜水令・猛想起那可意人儿，丰丰韵韵，忘昏失昼，情易舍业难酬。空着","p":"","d":"元代","a":"无名氏","c":["我见后思量，片时作念，独自亻孱亻愁。", "闷字儿常在心头。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"驻马听・蝶亻愁蜂亻孱，芳草天涯春事晚。莺慷燕懒，杏花帘幕雨声寒。","p":"","d":"元代","a":"无名氏","c":["秦楼寂寞玉箫闲，楚台容易朝云散。", "乍离别经这番，恁般懊恼谁曾惯。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"乔牌儿・行时思坐不安，所事儿怕干犯。多情反受风流难，旧愁积新恨","p":"","d":"元代","a":"无名氏","c":["亻赞。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"雁儿落・翠减了修眉柳叶弯，香消了娇脸桃花瓣。宽褪了纤腰翡翠裙，松","p":"","d":"元代","a":"无名氏","c":["绰了缕带鲛销襻。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"得胜令・自从那花底唱《阳关》，柳下送征鞍，经了些夜月孤帏静，望不","p":"","d":"元代","a":"无名氏","c":["见天涯一雁还。", "看看，业眼儿熬清旦；潸潸，泪珠儿落夜阑。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"甜水令・常记的《白雪》轻讴，金怀满泛，红牙低按，私语烛花残。到如","p":"","d":"元代","a":"无名氏","c":["今好梦全无，佳期易阻，相思成患，平白的废寝忘餐。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"折桂令・望蓝桥远似三山，烟水迷茫，道路艰难。瓶坠簪折，风酸月苦，","p":"","d":"元代","a":"无名氏","c":["雨涩支悭。", "长搀搀连理树柔条尽铲，碜可可比目鱼活水将干。", "他性格奸顽，不寄平安。", "章台柳恣意留连，蟾宫桂未许跻攀。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"随煞・怕的是无情岁月相催残，容易去何年重返。贾充宅韩掾见应难，天","p":"","d":"元代","a":"无名氏","c":["台路刘郎到来晚。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・夜行船","p":"","d":"元代","a":"无名氏","c":["院宇深沉人静悄，冷清清宝兽烟消。", "四壁秋虫，一帘疏雨，两般儿斗来相恼。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・一夜先争十岁老，闷厌厌情绪无聊。都为些子欢娱，霎时恩爱，惹一","p":"","d":"元代","a":"无名氏","c":["场梦魂颠倒。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾声・两三番个嫁字儿看看道道，来到口角头连忙咽了。今世里离散买休","p":"","d":"元代","a":"无名氏","c":["多，欢娱的到头少。", "纵有阳台无故人，空闲了雨雨云云。", "彩凤空闲，玉箫声尽，风月数载绝伦。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾声・求知人意相随顺，简帖儿须当再本。口儿里不抢白，心儿里便是肯。忆所见","p":"","d":"元代","a":"无名氏","c":["缺月风帘碎影筛，碧纱厨酒乍醒来。", "雾鬓支鬟，柳腰花面，多情恁时安在。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"风入松・杏花深处小亭台，犹作梦魂猜。东风邂逅逢娇态，麝兰散满闲阶。","p":"","d":"元代","a":"无名氏","c":["罗袜凌波半窄，春衫可体新裁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"落梅风・眉尖上眼挫侧，先留下几分恩爱。怕人知得地里佯不采，徐行过","p":"","d":"元代","a":"无名氏","c":["玉阑干外。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"胡十八・不下怀，自惊怪，悲间阻，想和谐，巫山依旧楚云埋。雁书又乖，","p":"","d":"元代","a":"无名氏","c":["鱼笺倦裁，一身无限愁，十日九番害。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"拨不断・细裁画，命合该，姻缘顷刻多成败。鬼病千般强打捱，凄凉万种","p":"","d":"元代","a":"无名氏","c":["难担载，几曾得片时轻快。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"离亭宴煞・楚阳台步步荆榛隘，担阁下两厢情色。相思卷何年结束，糊突","p":"","d":"元代","a":"无名氏","c":["谜甚日明白。", "传示你权宁耐，切莫把鲰生见责。", "是送暖的意儿虚，非偷香的性儿歹。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"天仙子・棘里兔，难配扑天鹄。馋眼痴心，看之不足。猛可里见姨夫，败","p":"","d":"元代","a":"无名氏","c":["坏风俗。", "好花怎教他做主，不辨贤愚。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"离亭宴煞・锦笺空写多情句，枉可惜口谈珠玉。假做苏卿伴侣，被冯魁已","p":"","d":"元代","a":"无名氏","c":["早图谋。", "使尽心，才得悟，则不如将取孛兰便数。", "咱看上脸儿甜，止不过钞儿苦。", "楚阳台远暮云遮，烟水恨连叠。", "沈郎多病腰肢怯，喜相逢可惯离别。", "悄悄鸳帏惭冷，薄怯怯绣衾空设。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"搅筝琶・空摧扌颠，直恁信音绝。欲寄相思，凭谁人话说。除纸笔，带喉","p":"","d":"元代","a":"无名氏","c":["舌，短叹长嗟。", "不流泪料来心似铁，寸肠千结。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"离亭宴煞・难睚漏水如年夜，正值着暮秋时节。坐不稳自敝自焦，睡不着","p":"","d":"元代","a":"无名氏","c":["不宁不帖。", "寒雁哀，寒蛩切，忽聚散阶前落叶。", "却是那透户一帘风，穿窗半弯月。", "夜阑深院暮寒加，愁听漏声多。", "银台画烛烧残蜡，伴离人心绪杂咱。", "有分红愁绿惨，无心赏白洒黄花。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"搅筝琶・《阳关》罢，香脸褪残霞。针线慵拈，匙杓倦把。和泪盼雕鞍，","p":"","d":"元代","a":"无名氏","c":["目断天涯，幽雅。", "离添病人憔悴煞，瘦得来不似人家。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"沉醉东风・全不想对月拈香剪发，指神誓奠酒浇茶。信口开，连心耍，向","p":"","d":"元代","a":"无名氏","c":["娼门买行踏。", "但有半句儿真诚敬重咱，无样般相思报答。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"离亭宴煞・早是可曾经心绪愁牵挂，又逢暮秋潇洒。恰不听寒蛩唧唧，又","p":"","d":"元代","a":"无名氏","c":["听的寒雁哑哑。", "傍枕衾，临床榻，暂合眼一时半霎。", "又听的疏雨洒窗纱，西风弄檐马。", "离情万金良夜霎时欢，犹恨不松宽。", "停延初试春风面，便安排病沈愁潘。", "从寄巧歌《金缕》，娇羞半掩霜纨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"新水令・乐昌妆镜破双鸾，今古恨短长亭畔。两下里几多般，受过的凄凉","p":"","d":"元代","a":"无名氏","c":["被俏萦占。", "分明少个莺花伴，奈今生缘分浅，凉打叠起更休算。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"搅筝琶・夕阳外，山隐隐水漫漫。似恁的凄凉，如何倒颠。终有日相逢，","p":"","d":"元代","a":"无名氏","c":["心苦眉攒。", "憔悴了玉容谁是管，越不成烟爨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"离亭宴煞・后期远约今秋判，那其间甚娘情款。受儿度枕冷衾寒，捱几宵","p":"","d":"元代","a":"无名氏","c":["月苦风酸。", "酒满斟，他亲劝，先摘得都无少半。", "本待一饮不留残，到被别离泪添满。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・珍珠马南情","p":"","d":"元代","a":"无名氏","c":["箫声唤起瑶台月，独倚阑干情惨切。", "此恨与谁说，又值那黄昏时节。", "花飞也，一点点似离人泪血。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"步步骄南・暗想当年，罗帕上把新诗写，偷绾同心结。心猿乘，意马劣，","p":"","d":"元代","a":"无名氏","c":["都将软玉温香，嫩枝柔叶。", "琴瑟正和协，不觉花影转过梧桐月。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"雁儿落北・不觉的梧桐月转过西银台上，昏惨惨灯将灭。怎禁他纱窗外铁","p":"","d":"元代","a":"无名氏","c":["马儿敲，这些时一团娇香肌瘦怯。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"沉醉东风南・一团娇香肌瘦怯，半含羞翠钿轻帖。微笑对人悄说：休负了","p":"","d":"元代","a":"无名氏","c":["今宵月。", "等闲间将海棠偷折，山盟共设：不许暂时少撇，若有个负心的教他随灯儿便灭。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"得胜令北・呀，若有一个负心的教他随灯灭，惨可可山盟海誓对谁说。海","p":"","d":"元代","a":"无名氏","c":["神庙现放着勾魂帖，那神灵仔细写。", "你休要心斜，非是掩难割舍；你休要痴呆，殷勤将春心漏泄。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忒忒令南・他殷勤将春心漏泄，我风流寸肠中热。因此上楚云深锁黄金阙，","p":"","d":"元代","a":"无名氏","c":["休把佳期暂撇。", "燕山绝，湘江竭，断鱼封雁帖。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"沽美酒北・湘北断鱼雁帖，他一去了信音绝，想着他负德辜恩将谎话说。","p":"","d":"元代","a":"无名氏","c":["眼见的花残月缺，自别来甚时节甚时节。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"川拨棹北・又被西风将锦帐揭，倚帏屏情惨切。这些时信断音绝，眼中流","p":"","d":"元代","a":"无名氏","c":["心内刀切，泪痕千叠，因此上渭城人肌肤瘦怯。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃红菊南・渭城人肌肤瘦怯，楚天秋应难并叠。停勒了画眉郎京尹，补填","p":"","d":"元代","a":"无名氏","c":["了河阳令满缺。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"七弟兄北・补填了河阳令满缺，一片似火也。心间事与谁说，好教我行眠","p":"","d":"元代","a":"无名氏","c":["立盹无明夜。", "今日个吹箫无伴彩云赊，闻筝的月下疏狂劣。", "画眉郎手脚拙，窃玉的性情别，把好梦成吴越。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"川拨棹南・成吴越，怎禁他巧言搬斗喋。平白地送暖偷寒，平白地送暖偷","p":"","d":"元代","a":"无名氏","c":["寒，猛可的搬唇递舌。", "水晶丸不住撇，点钢锹一味撅。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梅花酒北・他将那点钢锹一迷里撅，劈贤刀手中撇。打捞起块丹枫叶，鸳","p":"","d":"元代","a":"无名氏","c":["鸯被半床歇。", "胡蝶梦冷些些，破香囊后成血，楚馆着火焚者。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"锦衣香南・他将那楚馆焚，秦楼来拽。洛浦填，泾河截。梅家庄水罐汤瓶","p":"","d":"元代","a":"无名氏","c":["打为磁屑，贾充宅守定粉墙缺，武陵溪涧花儿钉了桩橛。", "楚襄王梦惊回者，汉相如赶翻车辙。", "深锁芙蓉阙，紫箫吹裂，碧桃花下凤凰将翎毛生扯。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"收江南北・呀，你敢在碧桃花下将凤毛扯，人生最苦是离别。山长永远路","p":"","d":"元代","a":"无名氏","c":["途赊，何年是彻，响当当菱花镜碎玉簪折。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"南吕・一枝花四景春","p":"","d":"元代","a":"无名氏","c":["衮香绵柳絮飞，飘白雪梨花淡。", "怨东风墙杏色，醉晓日海堂酣。", "景物偏堪，车马人游览，赏清明三月三。", "绿苔撒点点青钱，碧草铺茸茸翠毯。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梁州・流水泛江汀暖浪，轻云锁山市睛岚。恐无多光景疾相探。雕鞍玉辔，","p":"","d":"元代","a":"无名氏","c":["纱帽罗衫。", "珍羞满卓，玉液盈坛。", "歌姬舞妓那堪，诗朋酒侣相谈。", "生存花屋平昙，兴足竹林阮咸，醉居相府曹参。", "放开，酒胆。", "恨狂风尽把花摇憾，叹阳和又虚赚。", "拚了陶陶饮兴酣，于理相干。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・紫霜毫入砚深深蘸，吟几首莺花诗满函，一望红稀绿暗。正游入不甘，","p":"","d":"元代","a":"无名氏","c":["奈顽童执骖，不由咱卷把骄骏辔头儿揽。", "夏蔷薇满院香，菡萏双池锦。", "海榴浓喷火，萱草淡堆金。", "暑气难禁，天地炎蒸甚，闲行近绿阴。", "清风台榭开怀，傍流水亭轩赏心。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・倾残竹叶千尊，摘尽枇杷一树金。深喜娇娥见咱恁，向沙厨用心。安","p":"","d":"元代","a":"无名氏","c":["排下簟枕，专等归来醉时寝。", "秋金凤凋杨柳衰，玉露养芙蓉艳。", "竹轻摇苍凤尾，松密长老龙鳞。", "残暑都潜，爽气被楼台占，称情怀景色添。", "火龙鳞红叶萧萧，金兽眼黄花苒苒。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梁州・南浦晓云飞画栎，西山暮雨洒珠帘。小糟酒摘珍珠酽。银盘馔满，","p":"","d":"元代","a":"无名氏","c":["生鼎香粘。", "黄橙味美，紫蟹肥甜。", "趁苍空天似白亻兼，玩清光月拥银蟾。", "不学那愁脉脉呆汉江淹，则学兴悠悠诗仙子瞻，陶陶醉客陶潜。", "意忻金樽到手谁曾厌，我待把醉乡占。", "不管衣襟被酒淹，无事拘钳。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・赏心事休教欠，饮兴吟怀似妻添。醉倒尊前，任君潜扌弃。指点、便","p":"","d":"元代","a":"无名氏","c":["嫌，胜似你红尘路上险。", "冬青山失翠微，白玉无瑕玷。", "梨花和雨舞，柳絮带风ㄎ。", "泼粉堆盐，祥瑞天无欠，丰年气象添。", "乱飘湿僧舍茶烟，密洒透歌楼酒帘。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梁州・金盏内羊羔满泛，红炉兽炭频添。兰堂画角多妆点。锦茵绣榻，翠","p":"","d":"元代","a":"无名氏","c":["幕毡帘。", "鸾箫谩品，颦鼓轻敲。", "唱仙音余韵淹淹，捧牙版玉指纤纤。", "绮筵间盏到休推，宝鸭内香残再拈，玉壶中酒尽重添。", "况兼、兴タ。", "金波潋滟霞光闪，接入手不辞厌。", "为爱琼瑶尽意瞻，赏玩休嫌。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梁州・昨日闹垓垓兵临孟水，今日冷清清草满章华。叹兴亡世事如嚼蜡。","p":"","d":"元代","a":"无名氏","c":["则不如ド半缸绿蚁，啜一盏清茶。", "感时怀苦，对景嗟呀。", "水穿云碧玉流霞，山叠翠青锦蒙纱。", "黄菊绽猛兽睁睛，红叶落火龙退甲。", "苍松盘怪蟒张牙。", "景幽，静雅。", "一轮皓月林梢挂，醉后将骞驴跨。", "稚子山妻引到家，煞强如大纛高牙。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・南山射虎弓藏，北海诛龙剑隐匣。两字功名不牵挂，书房中卧咱。松","p":"","d":"元代","a":"无名氏","c":["阴下坐咱，无是无非快活煞。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"越调・斗鹌鹑忆别","p":"","d":"元代","a":"无名氏","c":["焰腾腾祆庙烧残，白茫茫蓝桥水起。", "昏邓邓楚岫云遮，黑淹淹阳台路迷。", "桃源洞雾锁云埋，武陵溪砖填土塞。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"紫花儿序・冷落了流苏绣幕，萧疏了画阁兰堂，寂寞了锦帐罗帏。生折散","p":"","d":"元代","a":"无名氏","c":["鸾孤凤只，硬分开燕约莺期，暗暗的伤悲，永远山长隔万里。", "一思量一番憔悴，离愁断九曲柔肠，蹙损了八字蛾眉。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"小桃红・伯苏东云燕西飞，一点芳心醉。鱼雁无凭怎寻觅，信音稀。牙床","p":"","d":"元代","a":"无名氏","c":["冷落了鸳鸯被，减尽了千娇百媚。", "害的人一丝两气，方信道最苦是别离。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"耍厮儿・美恩情眉南面北，好姻缘画饼充饥，相逢笑谈除是梦里。这凄凉","p":"","d":"元代","a":"无名氏","c":["怎支持？谁知！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"圣药王・想着我星月底，言海誓，尽今生一世效于飞。我如今废寝忘餐染","p":"","d":"元代","a":"无名氏","c":["病疾，上看山不见故人回，险化做望夫石。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾声・别离苦恨从头记，有一日捱出凄凉日期。则俺那薄幸短命若回程，","p":"","d":"元代","a":"无名氏","c":["我将这一件件一桩桩诉与你。", "小令。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"仙吕・小醋大情","p":"","d":"元代","a":"无名氏","c":["暗潮拍岸，断江风扫芦花，鸥鹭破烟飞落汀沙。", "见渔舍两三家，在夕阳下，一簇晚景堪画。", "闷无语时将珠泪洒，愁转加，瘦损丰标只为他。", "事萦心鬓添白发，蹉跎负却年华。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"正宫・白练序春愁","p":"","d":"元代","a":"无名氏","c":["沉吟久，奈何事从来不自由？芙蓉帐未暖又还分手，别后万种愁。", "叹晓梦高唐一旦休，添亻孱亻愁。", "梨花细雨，燕子空楼。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"太平令・消瘦纤腰似柳，近日绛裙罗带频收。闲衾易冷，人在小小云兜，","p":"","d":"元代","a":"无名氏","c":["堪羞。", "凄凄孤影伴灯篝，倚窗下倦听银漏。", "这般时候，三更酒醒，满枕春愁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"捣白练・绸缪，两配偶，思量起故友。在花阴下同欢会，燕侣鸾俦。无由","p":"","d":"元代","a":"无名氏","c":["愿再酬，恨飞絮飘香逐水流，成迤逗。", "钗分凤折，线断银钩。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"太平令・悠悠，青霄路有，绣鞍归晓，山盟虚缪。分开美玉连环结，未能","p":"","d":"元代","a":"无名氏","c":["够两情依旧。", "频修银笺锦字到皇州，每一字字泪痕湮透。", "甚时相守，金杯满酌，艳曲低讴。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"破挂真・引子忆别娇容情分浅，终朝废寝忘餐。离绪恹恹，情怀攘攘，别","p":"","d":"元代","a":"无名氏","c":["后又添悒怏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"绣带宜春令・幽窗下沉吟半晌，追思俏的娇娘。娉婷处不弱似莺莺，娇娆","p":"","d":"元代","a":"无名氏","c":["处可比双双。", "非奖，最堪夸他性格儿温柔，难描他身材儿生得停当。", "说不尽风流可喜，万般模样。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"太平白练序・想当日月下星前，吐胆倾心，把誓盟深讲。行思坐想，望尽","p":"","d":"元代","a":"无名氏","c":["老今生，同佼攵鸾凰。", "谁想，蓦然平地浪波生，怎知道祸从天降。", "雾迷云障，被鸨母苦死打开怨鸯。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"三段鲍老催・此情怎当，罗衣尚存兰麝香。鸾笺仗托纸半纸，人何在，谩","p":"","d":"元代","a":"无名氏","c":["叹息，空惆怅。", "恼得潘郎两鬓似霜。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"出队莺乱啼・咱这里因因他来狂荡，他因咱痛感伤。几番欲待不思量，不","p":"","d":"元代","a":"无名氏","c":["思量以后怎做得铁打心肠？江淹闷，韩生忿，怎么得咱家闷？千般恨才离了心上，又早来蹙在眉尖。", "天还可怜，便霎时相见又且何妨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"南吕・香遍满闺情","p":"","d":"元代","a":"无名氏","c":["鸾凰同聘，寻思那时忒志成。", "谁信今番心不定，顿将人来薄幸。", "可怜无限情，也似纸样轻，把往事空思省。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"懒画眉・花开花谢闷如醒，日远日蔬冷似冰，眼前光景总凄清。漫水流花","p":"","d":"元代","a":"无名氏","c":["径，庭院黄昏门半扃。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"挂梧桐・谩教人忆茂陵，调琴谁共听？少个知音，斗帐沉烟冷。孤眠最若，","p":"","d":"元代","a":"无名氏","c":["怕良宵永，这样凄凉如何教我捱到明。", "心肠纵然如铁硬，苦也思量，扑扑簌簌泪倾。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"浣溪沙・谁惯轻，害相思病，怨只怨枕闲衾剩。两三杯酒全无兴，空教我","p":"","d":"元代","a":"无名氏","c":["十二栏干独自凭。", "心耿耿，想起虚脾情；耳边言，那取真本兰亭。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"刘泼帽・对景、对景无心咏，倦时闻枝上流莺。如何唤的春愁醒？羞对画","p":"","d":"元代","a":"无名氏","c":["花间翡翠双双并，万虑生，独守着房栊静。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"东瓯令・人何在，梦难成。永远山遥不计程，雕鞍宝马无踪影。他那里胡","p":"","d":"元代","a":"无名氏","c":["行径，朱颜绿鬓易凋零，无奈痛伤情。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"金钱花・想你掩耳偷铃，为你缄口如瓶。待君归兮细评论，夫妻债雁同鸣，","p":"","d":"元代","a":"无名氏","c":["欢会事凤和鸣。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・金钗钿盒重新整，翠被香温叙旧情，鲛绡带绾重再整。四时思慕","p":"","d":"元代","a":"无名氏","c":["柳径花溪，梅梢褪粉丽日迟，桃杏芬芳蜂媒蝶使。", "树拖烟笼绿柳，柳花绵片片飞。", "为咱思念伊，恐怕春又归。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"东瓯令・花容貌，柳颦眉，云鬓堆鸦，温柔旖旎。方才款步我这金莲浸罗","p":"","d":"元代","a":"无名氏","c":["袜冷，腾腾困困娇无力。", "雕栏曲槛，游蜂粉蝶飞，婷婷袅袅欲缓迟。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"四团花・懒懒愁画眉，看看身渐蠃，情书欲写无凭寄。不见才郎，何时归","p":"","d":"元代","a":"无名氏","c":["把阑干遍倚，将花头倦折。", "莺声呖呖，芳心自知。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"东瓯令・薰风至，火云飞，则见那萱草葵榴初绽蕊。炎天酷暑浑无寐，迷","p":"","d":"元代","a":"无名氏","c":["迷闷闷醒如醉。", "自怜月下月下影儿随，悒悒怏怏懒入罗帏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梧桐树・泪暗垂，添憔悴，渐渐的这腰肢掩过裙儿衤至。一声、一声，塞","p":"","d":"元代","a":"无名氏","c":["雁、塞雁，伤泪滴，远望云山，信杳音稀。", "未知多情把奴山盟记，莫得要再求，再求新亲配美。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"东瓯令・梧桐叶，晚风吹，则这无限的离情我便分付与谁？蓦听的阶下数","p":"","d":"元代","a":"无名氏","c":["声寒蛩叫，扑扑簌簌红叶儿坠。", "碧天寒雁听了感伤悲，凄凄凉凉越添病疾。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"浣溪沙・雪片飞，寒风起，闷恹恹自守孤帏。薄衾寒浸透香肌，盼情人阻","p":"","d":"元代","a":"无名氏","c":["隔何日归。", "戍楼悠悠《三弄》品，气丝丝废寝忘食。", "鸾笺锦字诉与别离，痛伤情泪痕湮透湿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"东鸥令・朔风紧，冻云垂，灵鹊儿檐间喳喳的来报喜。不承望今夜画堂里","p":"","d":"元代","a":"无名氏","c":["刚刚的重完全，双双共入罗帏里。", "欢娱无奈被这晓鸡啼，咭咭聒聒好梦惊回。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"商调・字字锦","p":"","d":"元代","a":"无名氏","c":["群芳绽锦鲜，香逐东风软。", "莺簧转巧声，题起伤春怨。", "睹名园，杏障桃屏，桃屏上映着柳眉翠钿。", "天天，桃花窨约，恰似去年。", "因何去年、去年人不见，空蹙破两眉翠尖。", "奈奈山长永远，他在那里和谁两个欢欢喜喜？咱这思思想想，寻寻觅觅，欲待见他一面。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赚・离绪恹恹，奈少个人儿在眼前。空嗟怨，不知何日再团圆。泪涟涟，","p":"","d":"元代","a":"无名氏","c":["极目关山隔雾前，写下花笺谁与传？心事无告托，冤家直恁误人方便，怎生消遣。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"满园春・南楼外雁翩翩，悄没个音信传。长空败叶飘飘舞，金风动，铁马","p":"","d":"元代","a":"无名氏","c":["儿声喧，纱窗外透银蟾。", "想杀人也天，盼杀人也天，短命冤家，音稀信杳，莫不误约盟言。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺篇・彤云布，朔风起，遍长空柳花飘棉。几朵早梅开放蕊，销金帐共谁","p":"","d":"元代","a":"无名氏","c":["两个欢宴？独自个守炉边。", "想杀人也天，盼杀人也天，短命冤家，音稀信杳，莫不误约盟言。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・一机锦离思","p":"","d":"元代","a":"无名氏","c":["宝钗分，鸾镜缺，瓶坠簪断折，《三叠阳光》争忍，别。", "心儿里痛哽咽，眼儿里弹泪血。", "空教我扌绝耳揉腮，执手和伊相看，也没一句话儿说。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"江儿水・又早三秋至，寒雁飞。牛星女宿重相会，只听的捣砧声透入在罗","p":"","d":"元代","a":"无名氏","c":["帏内。", "景凄凉阶下寒蛩唧，桂子飘香拂鼻。", "叶落丹枫，满目黄花铺地。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"南吕・一剪梅秋闺思","p":"","d":"元代","a":"无名氏","c":["草满中庭苔满墙，雨潇潇风送幽窗，此凄凉外怎不凄凉？无限心机，多病相妨。", "玉笋重弹孤凤凰，一蓦来地远山长。", "杯深蘸甲润鹅黄，今夜醺醺，有个商量。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"采桑子・辘轳金井梧桐晚，几树惊秋，昼雨和愁。百尽虾须在玉钩，琼窗","p":"","d":"元代","a":"无名氏","c":["春暖双蛾皱。", "回首头边，欲寄鳞游，九曲寒波不逆流。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"木兰花慢・爱幽花带露，凝晓色淡秋塘。恨太华峰高，庐山社远，尘世相","p":"","d":"元代","a":"无名氏","c":["谁争半溪佳景？且闲将华发照沧浪。", "羡煞风流公子，一生何限清香？仙家幽野水云乡，高韵却浓妆，看脉脉盈荷觞。", "明日醒来，华信新声，付与秋娘。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"惜芳春・绿柳长亭晚，珠帘卷暮寒。闷对东风掩泪眼，桃花谢，杏花残。","p":"","d":"元代","a":"无名氏","c":["人未还，盼雕鞍和月凭栏杆。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・仙吕/点绛唇","p":"","d":"元代","a":"王晔","c":["俺则见四野田畴，禾苗丰茂。", "登场后，鼓腹歌讴，现如今无士马绝征斗。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・油葫芦","p":"","d":"元代","a":"王晔","c":["你两个自小儿相随到白头，端的是老故友，但同行共坐笑无休。", "我则道别逢闲汉频摇手，你可也敢则是饱谙世事慵开口。", "俺则见这壁厢闷闷的迎，那壁厢郁郁的忧。", "(带云)伯伯。", "(唱)你为甚么这等悄无言则办的眉儿皱，泪簌簌不住点儿流？(云)伯伯，我去整治些酒菜儿来，与俺父亲饮几杯去。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・天下乐","p":"","d":"元代","a":"王晔","c":["却不道一盏能消万古愁，则俺这村也波坊，不比那府共州，那里取笙歌绮罗拥上楼。", "这快乐俺这里无，这快乐您那里有。", "伯伯也俺这里止不过是村务酒。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・寄生草","p":"","d":"元代","a":"王晔","c":["俺这里有的是黄鸡嫩，白酒熟，伯伯也你莫不为茅檐草舍庄家陋？(彭大云)俺每都是庄农人家，一村疃儿居住的，有甚么好房子在那里？(正旦云)我也道来。", "(唱)也一般儿青山绿树风光秀，(带云)况我父亲呵，(唱)又和你倾心吐胆交情厚。", "(彭大云)儿也，你不知道。", "我家主人周公，今日与我算一卦，道我没寿，以此吃酒不下。", "(正旦云)伯伯，你没寿今年也六十九岁了。", "(唱)但愿的乐丰年醉倒有百千场，何必要炼丹砂学取那松乔寿？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・后庭花","p":"","d":"元代","a":"王晔","c":["你则管里絮叨叨说事头，舌剌剌不住口。", "你便待准备着哭啼啼长休饭，伯伯也咱与你换上这喜孜孜欢庆酒。", "休得要泪交流，我着你依前如旧，包管你病羊儿奔似虎彪，困鱼儿脱了钓钩。", "(彭大云)我那周公开了三十年卦铺，止算差的一个，你怎么道他又算差了？(正旦唱)倒将咱佯不瞅，说周公百事有。", "转阴阳得自由，更山川变宇宙。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・柳叶儿","p":"","d":"元代","a":"王晔","c":["你卖弄他光前、光前绝后，不由我不邓邓火上浇油。", "(彭大云)如今世上，除了那周公一人妙算，再无敌对哩。", "(正旦唱)你道是周公世上无敌手，早激的我嗔难忍，怒难收，伯伯也则教他到我行纳下降筹。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・赚煞","p":"","d":"元代","a":"王晔","c":["直等到月转矮墙西，人约黄昏后。", "摆祭物浇茶奠酒，只待那七位星官来领受。", "伯伯也早唬的你颤笃波魂魄悠悠，那其间你可便休落了芒头，要记的语句儿滑熟，(彭大云)那星官是甚么形相？我可害怕，怎生告他来？(正旦唱)忍着怕担着惊告北斗，比似你做阴司下鬼囚，争似得他这天堂上阳寿，(带云)伯伯，则今夜且和俺父亲吃一个烂醉者，(唱)管着你笑吟吟同做醉乡侯。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・正宫/端正好","p":"","d":"元代","a":"王晔","c":["则为这镜儿昏，我可也难梳裹，就东庄头巧匠明磨。", "去时节大斋时，急回来可早日头儿末，不知俺家中有甚的人焦聒。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・滚绣球","p":"","d":"元代","a":"王晔","c":["我头直上发似揪，耳轮边热似火。", "我行行里袖传一课，急慌忙把脚步儿频挪。", "我这里穿人道桑拓林，穿小径荆棘科。", "(带云)早来到门首也。", "(唱)则见乱交加不知是那个，则听的沸滚滚热闹镬铎。", "(任二公云)彭大公，你使这等见识，我拼的和你做一场。", "(正旦唱)俺父亲揎拳捋袖因何事？(彭大云)你要打我么？由你打，由你打，只要许了这亲事便罢。", "(正旦云)原来是彭大公。", "(唱)他这般唱叫扬疾，不徕，便可也为甚么？(彭大做见正旦科，云)好、好、好！女孩儿来了也。", "我有说话，要和你讲哩。", "(正旦唱)有甚的好话评跋？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・倘秀才","p":"","d":"元代","a":"王晔","c":["那问亲的无礼法将我来劫夺，若是我不许聘我可有甚么罪过？(彭大云)哎哟！你这小孩子家就学得放泼那？(正旦唱)知他是您行凶也那我放泼？(媒婆云)喜事不要嚷！姐姐，你则许了罢。", "(正旦唱)你休言语，怎成合，可正是望梅止渴。", "(彭大云)孩儿也，周公家这门好亲事，我可着你受用一世儿哩。", "我就与你做个落花的媒人，也不亏了你。", "(正旦云)谁听你这话来？(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・滚绣球","p":"","d":"元代","a":"王晔","c":["则你这媒人一个个，啜人口似蜜钵，都只是随风倒舵，索媒钱嫌少争多。", "女亲家会放水，男亲家点着火，你将那好言语往来收撮，则办得两下里挑唆。", "你将那半句话搬调做十分事，一尺水翻腾做百丈波，则你那口似悬河。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・叨叨令","p":"","d":"元代","a":"王晔","c":["你道是石哥哥我不合救了他亡身祸，因此上被周公家知道我这赔钱货。", "我则道多是你这撮合山要赚松纹锞，那里管赤绳儿曾把姻缘缚？兀的不气杀人也波哥，兀的不气杀人也波哥。", "(带云)彭大公，你好歹也！(唱)我则问你个彭大公怎么的也这等迎风箕欠。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・呆骨朵","p":"","d":"元代","a":"王晔","c":["想当日泪漫漫哭的你那喉咙破，怕不眼睁睁的待见阎罗。", "周公也他算着你身亡，我端的救了你命活。", "(彭大云)儿也，你是我的恩人，怎忘得你？(正旦唱)哎！你个彭大公才得消磨难，倒着我桃花女平白地遭摧挫。", "(彭大云)这是周公家要求媳妇，干我甚事？(正旦唱)也是我不合搭救你，你将这恶言词展赖我。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・伴读书","p":"","d":"元代","a":"王晔","c":["你休则管里闲撺掇，休则管里空担荷。", "我如今绿鬓朱颜如花朵，我又不苍颜皓首年高大。", "到来日你可便牵羊携酒来相贺，(带云)大公也。", "(唱)你看道是谁家结下丝萝。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・煞尾","p":"","d":"元代","a":"王晔","c":["则怕我到家来有危有难如何躲，我劝你所作依公莫太过。", "投至得到我根前问个定夺，讨个提掇，决个死活。", "哎！周公徕，你便有灵验的阴阳，敢可也近不的我。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・彭大云","p":"","d":"元代","a":"王晔","c":["兄弟，你女儿己许下亲事，我便与媒婆回周公话去也。", "(做别科)(任二公做扯住科，云)哥哥也，还吃钟喜酒去。", "(媒婆云)任二公不劳了。", "周公在那里悬望，要准备下财礼迎娶过门，许多事务，都只在明日一日，放彭大公早些去罢。", "(任二公云)这等，一发待成亲之后，同你来吃喜酒便了。", "(同下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・中吕/粉蝶儿","p":"","d":"元代","a":"王晔","c":["别人家聘女求妻，也索是两家门对，写婚书要立官媒。", "下花红，送羊酒，都选个良辰吉日。", "大纲来为正礼当宜，那里取这不明白强人婚配？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・醉春风","p":"","d":"元代","a":"王晔","c":["你去那《周易》内显神通，怎如我六壬中识详细。", "也不待到家门就要算的我一身亏，你道波可有这个理、理？由你有百般的阴谋，千般的巧计，怎当我万般的堤备。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・迎仙客","p":"","d":"元代","a":"王晔","c":["他道是日游神为祸祟，我桃花女受灾危，怎知有千只眼先驱能辟鬼？(媒婆做扶出门科)(正旦唱)我行出宅门前，离得这闺阁里。", "我呵若不是妆束巍巍，险些儿被金神打的天灵碎。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・醉高歌","p":"","d":"元代","a":"王晔","c":["坐车儿倒背我这身奇，手帕儿遮檬了我面皮。", "(彭大云)怎么这新人车儿不向前走，到往后退那？(正旦唱)大公也，你可怎生不解其中意，我则怕撞着那凶神的这太岁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・石榴花","p":"","d":"元代","a":"王晔","c":["今日是会新亲待客做筵席，倒准备着长休饭、永别杯。", "莫不找拜先灵打着面豹纛旗，你畅好是下的。", "使这般狡幸心机。", "娶新人指望成佳配，结百年谐老大妻。", "怎么未成亲先使这拖刀计，早难道人善得人欺。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・斗鹌鹑","p":"","d":"元代","a":"王晔","c":["你送的我九死一生，哎！周公也枉坏了你那三财的这六礼。", "(做倒席行科，彭大云)你只管里把这两领席，倒来倒去，是甚么主意？(正旦唱)这的是我避难的机谋，躲灾的见识。", "为甚么走走行行铺下净席？则要你盖了这里。", "他拣定这黑道的凶辰，(带云)我将这净席呵，(唱)与他换过了黄道的吉日。", "(彭大云)这一会儿可不听的他言语了，待我看咱。", "(做看正旦科)(正旦云)伯伯，你看我怎的？(彭大云)没。", "(周公上，问彭大科，云)如何？(彭大云)不济事。", "(周公云)这一番准着他板僵身死。", "(彭大云)他还活活儿的哩！(周公云)他怎生活了来？(彭大云)他早知道了，说今日是黑道日，他把两领净席，铺在地下，行一领倒一领，换过黄道走了，因此他可不死，还是活活儿的哩。", "(周公云)嗨，这妮子好强也。", "(彭大云)你可不济哩。", "(周公云)等我再算一卦。", "乾、坎、艮、震、巽、离、坤、兑。", "如今他该入门了，正是星日马当直，新人犯了他，跑也跑杀，踢也踢杀。", "怕他不板僵身死？彭祖，你去请新人入门咱。", "(下)(彭大做摇头科，云)周公，你好忒狠也！媒婆，扶着新人入门者！(正旦云)且慢者！今日是星日马当直，我过的这门限去。", "正汤着他脊背，可不被这马跑也跑杀，踢也踢杀，那里取我的这性命来？石小大哥，与我取马鞍一副，搭在这门限上波。", "(石留住做搭马鞍科)(彭大云)他把门限上放上这马鞍子，又做甚么勾当？(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・上小楼","p":"","d":"元代","a":"王晔","c":["你争知就里，阴阳凶吉。", "现如今星日马当日，降临凡世，正是该期。", "我可也怎敢的，擅便道，汤他脊背？先与他停停当当，鞍上这一重鞍辔。", "(彭大云)嗨，这一会儿我可不听见他言语了。", "(做看正旦科)(正旦云)伯伯，你看我怎的？(彭大云)没。", "(周公上，问彭大科，云)如何？(彭大云)罢么，我道你老了不济事了。", "(周公云)他可板僵身死了么？(彭大云)老官人，他还活活儿的哩。", "(周公云)他怎的活了来？(彭大云)我去请他入门。", "他道今日是星日马直日，把一副鞍子来搭在门限上，那马便顺顺的伏了他，跑也不敢跑一跑，踢也不敢踢一踢，因此不死，还活活儿的哩。", "(周公云)这妮子好强也。", "(彭大云)我说道，你可不济事哩。", "(周公云)等我再算一卦。", "乾、坎、艮、震、巽、离、坤、兑。", "我如今请他入这墙院子来，却是鬼金羊，昴日鸡当直。", "这两个神祗巡绰，若见了新人呵，鸡儿啄也啄杀他，羊角儿触也触杀他，必然板僵身死也。", "(下)(彭大做掩泪科，云)儿口乐，这一番可送了孩儿的性命也。", "媒婆，请新人入墙院子来，(媒婆做请科)(正旦云)且慢者！这早晚正值鬼金羊，昴日鸡两个神祗巡绰，我入这墙院子去，必受其祸。", "石小大哥，取一面镜子来，与我照面，再取那碎草米谷，和这染成的五色铜钱，等我行一步，与我撒一步者。", "(石留住云)兀的不是镜子？我便撒那碎草米谷去。", "(正旦做取镜，自照科)(石留住做撒草谷科)(彭大云)这孩儿有许多琐碎。", "(媒婆做扶入墙院科)(正旦云)伯伯，你可那里知道？(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・幺篇","p":"","d":"元代","a":"王晔","c":["我着这草喂了羊，谷喂了鸡。", "(带云)这铜钱呵，(唱)着小孩儿每，吵吵闹闹斗争相戏。", "趁哄里，向堂前，将身平立。", "哎！周公也可早则颓气了你那巽离坤兑。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・普天乐","p":"","d":"元代","a":"王晔","c":["我这里说真实，言端的今日是犯着丧门吊客。", "我早把弓箭忙射，弓拽开似明月弯，箭发去似流星坠。", "(石留住云)关上门者，等我射箭。", "一箭，两箭，三箭。", "(正旦唱)我这里笑吟吟挪身来宅内，周公也可不教我直挺挺板死在门闱？羞杀你晓三才的孔明，知六壬的鬼谷，画八卦的伏羲。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・快活三","p":"","d":"元代","a":"王晔","c":["我则怕这雷霆白虎威，因此上要一个做相陪。", "忽被那鼓声惊动怎支持，倒惹了你的凄惶泪。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・尾煞","p":"","d":"元代","a":"王晔","c":["算人间死与生，较阴阳高共低。", "再休提天文地理星家历，周公也你在我桃花女根前如何过去得。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・双调/新水令","p":"","d":"元代","a":"王晔","c":["则问你为甚么腰横利斧出城东，怎生的我根前还来打哄？我心间无限事，尽在不言中。", "不由我忿气冲冲，谢得公婆家将俺来厮知重。", "(彭大云)儿也，实不相瞒，委的是周公着我砍桃树儿去哩。", "(正旦云)伯伯，想当初是我救你来，今日可要你救我。", "(彭大云)儿也，你着我今日可怎生救你？(正旦云)伯伯，你砍那桃树去，休要伤了他根儿，你只半中间砍折。", "你若拿这桃枝进门，那时节我须死了。", "只要你记着我的言语，将那桃枝去门限上敲一敲，着周公家死一口。", "(彭大云)敲两敲呢？(正旦云)着周公家死两口。", "(彭大云)敲三敲呢？(正旦云)死三口。", "(彭大云)这等我直敲到晚，只是你不死。", "我与你报冤便好。", "你也死了，就把周公家七代先灵都死绝了。", "你怎得见？(正旦云)只等周公死后，你向我耳朵根边高叫三声：桃花女快苏醒者！我便得还魂也。", "(彭大云)这话有准么？(正旦云)岂有不准之理？(彭大云)孩儿放心，我牢记着哩。", "我如今砍桃树去也。", "(下)(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・雁儿落","p":"","d":"元代","a":"王晔","c":["我这里困腾腾睡正浓，则听的闹嚷嚷声惊动。", "还不够半竿日影斜，早唤醒一枕游仙梦。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・得胜令","p":"","d":"元代","a":"王晔","c":["呀，笑杀那注《易》的老周公，枉了也砍折这小桃红。", "他道是推休咎凭他用，怎如我转阴阳妙不穷。", "他道是英雄，要把我残生送。", "我如今从也波容，也等他一家儿似梦中。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・川拨棹","p":"","d":"元代","a":"王晔","c":["你须是俺公公，比旁人自不同。", "我实指望承奉欢容，扶助家风。", "怎知你逞尽顽凶，设就牢笼，不许我身安寿永，到今日爻与卦两无功。", "(周公云)媳妇儿，你则可怜见，救我两个孩儿咱。", "(正旦再用水喷增福科)(增福做醒科)(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・收江南","p":"","d":"元代","a":"王晔","c":["呀，今日个桃花依旧笑春风，再不索树头树底觅残红。", "多谢你使心作幸白头翁，若不是这些懵懂，怎能够一家儿团聚喜融融？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃花女破法嫁周公・鸳鸯煞尾","p":"","d":"元代","a":"王晔","c":["从今后再休提一求一肯机谋中，越显你千占千验声名重。", "也不索家贮神龟，户纳钱龙。", "畅道术似君平，财如邓通，赢得个车马填门四远里人传颂。", "你知我为甚的所事儿玲珑？则我这桃花元是那上天的种。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾声・若道是成就了洞房中惜玉怜香愿，媒合了翠馆内清风皓月筵，六片","p":"","d":"元代","a":"萨都剌","c":["儿香皮做烟眷。", "茶コ架边，蔷薇洞前，管教你到底团圆不离了半步儿远。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・仙吕/赏花时","p":"","d":"元代","a":"无名氏","c":["母亲道年长青春未配人，我拚了个雨打梨花深闭门。", "我怎肯将名利似浮云。", "(夫人云)孩儿，你则不出门呵便了也。", "(正旦唱)我从来有忠信，(云)父亲母亲你但放心。", "梅香，俺回去来。", "(唱)我又索纱窗下捱黄昏。", "(同梅香下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・仙吕/点绛唇","p":"","d":"元代","a":"无名氏","c":["你看那绿柳低垂，燕雏成对，莺声碎。", "花老芳池，一派游春意。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・混江龙","p":"","d":"元代","a":"无名氏","c":["非是我懒临园内，隔花阴怕有外人知。", "自从我初离绣幕，莲步轻移。", "春事已随流水去，落花空惹杜鹃啼。", "冷清清花影疏林内，我则见山光隐隐，绿柳依依。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・油葫芦","p":"","d":"元代","a":"无名氏","c":["二月江南莺乱啼，绕花阴双燕飞，则见那秋千闲控玉人归。", "(梅香云)可惜我们不曾拿的酒来。", "姐姐，你且在这里耍，我去崇文门外头买两瓶酒来你吃。", "(正旦唱)便休将诗酒为佳致，可不道山翁之兴何须醉。", "(梅香云)姐姐，你看那梨花，桃花杏花开的真是好看。", "(正旦唱)梨花开雪片妆，桃花放红焰飞。", "你看那浸浸红杏烧林际，端的可也不尽眼中题。", "(梅香云)无一个人也呵。", "(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・天下乐","p":"","d":"元代","a":"无名氏","c":["抵多少宴罢青楼月下归，不由我猜疑，心上喜。", "(梅香云)姐姐。", "你喜欢甚么？(正旦唱)牡丹风似人摇锦机。", "趁风和花草香，落残红衬燕泥，我则索慢行过芳树底。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・鹊踏枝","p":"","d":"元代","a":"无名氏","c":["我这里猛听的，似呆痴。", "又不是月下星前，暗约偷期。", "不由我听沉了半会，是谁人乱作胡为？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・寄生草","p":"","d":"元代","a":"无名氏","c":["又不曾待月在西厢下，听琴在旅店里。", "踏青惹下弥天罪，赏春光引起鸳鸯会，看群花误到天台地。", "(云)我依着你。", "我吟一首诗，看他说甚么。", "紫燕双双起，鸳鸯对对飞。", "无言匀粉面，只有落花知。", "(赵匡义云)好个聪明女子也。", "我出去见他一面，怕些甚么。", "(做见科，云)小娘子拜揖。", "(正旦云)先生万福。", "一人好聪明俊秀才！(唱)我见他乌纱小帽晃人明，久以后必然金榜题名讳。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・醉中天","p":"","d":"元代","a":"无名氏","c":["正二九青年际。", "(赵匡义云)曾许聘他人不曾？(正旦唱)不曾得见良媒，独倚纱窗懒画眉。", "(赵匡义云)小娘子，小生愿为媒证，许聘他人，可不好那。", "(正旦唱)多谢你相周济。", "争奈听姻缘事迟，城难躲避，我又怕惹蜂蝶泄漏春机。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・金盏儿","p":"","d":"元代","a":"无名氏","c":["也是我命低微，惹灾危，若是俺尊堂知道可也甘当罪。", "(赵匡义云)这厮合死也。", "(正旦唱)他那里揎拳裸袖皱双眉。", "(韩松云)这个是甚么人？我怕你不成也。", "(正旦唱)那里也画堂欢宴，早难道是花下燕莺期。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・赚煞尾","p":"","d":"元代","a":"无名氏","c":["不承望有今朝，到着我愁无计，又怕俺双亲得知，忙步金莲趁早回，休忘厂蝶使蜂媒。", "(赵匡义云)小娘子，我便着官媒来议亲也呵。", "(正旦唱)便休要忒延迟误了佳期，准备兰堂宴罢归。", "(家童冲上，云)姐姐，相公有请。", "(梅香云)叫我们哩。", "我去来。", "(正旦唱)你休要喧喧闹起，再无个商议。", "(云)二舍，你休怪，我去也。", "(唱)抵多少青楼歌罢宴酣回。", "(同梅香家童下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・南吕/一枝花","p":"","d":"元代","a":"无名氏","c":["俺须是官员仕宦家，又不是黎庶闾阎客。", "俺兄弟养成彪虎志，久以后必有胆天才。", "好着我心下疑猜，恨不的两步为一蓦，急煎煎不放怀。", "俺兄弟困恹恹病在膏肓，猛可里便苦腾腾石沉大海。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・梁州","p":"","d":"元代","a":"无名氏","c":["自从俺已有了徐卿二子，怕甚么令巍峨王氏三槐。", "俺门户中未有三千客，出来的谈天论地，胸卷江淮。", "不离了龙韬虎略，弓箭旗牌。", "展胸襟个个英才，论机谋转转安排。", "大兄弟虎狼丛惹事招非，刀剑洞大宽地窄，死生巢一迷里裁排。", "威哉？壮哉？博一个腰金衣紫官三代。", "暗地里自分解，不知是暑湿风寒天降来，不见个明白。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・隔尾","p":"","d":"元代","a":"无名氏","c":["他莫不是功名不遂心无奈？(赵弘殷云)不是。", "(正旦唱)他莫不是思念哥哥不下怀？(赵弘殷云)不是。", "(正旦唱)莫不是少欠人钱使人怪？(赵弘殷云)不是。", "孩儿，你都猜不着。", "(正旦唱)这谜儿怎猜。", "我实难布摆。", "天那，莫不他斗打相争受了些外人的歹？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・牧羊关","p":"","d":"元代","a":"无名氏","c":["见兄弟面色儿恹恹瘦，容颜儿惭惭改，怎生来形体如柴。", "(云)兄弟，你这病我试猜咱。", "(赵匡义云)姐姐。", "我试猜咱。", "(正旦唱)莫不为身事难求？莫不为经营买卖？赵匡义云)不是。", "你猜不着。", "(正旦唱)莫不是霜露侵肌体？莫不是月下被风筛？(赵匡义云)都不是。", "(正旦唱)止不过心念别姻眷，一庄庄我自猜。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・骂玉郎","p":"","d":"元代","a":"无名氏","c":["我这里听言道罢添惊怪，有甚么难分诉你与我诉个明白。", "你莫不在章台走马垂杨陌？(赵匡义云)姐姐，我这病则为前日赏春去，遇着个女子，以此上得了这个病证也。", "(正旦唱)您将那心上愁，腹内思，悦与我方何碍。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・感皇恩","p":"","d":"元代","a":"无名氏","c":["呀，便着你鱼水和谐，你也可稳放宽怀。", "我如今遣官媒，亲问候，便有个好音来。", "(赵匡义云)姐姐，你不知韩松那厮，倚逞权豪，他要强娶他哩。", "(正旦云)不妨事。", "(唱)遮莫他官居一品，怕甚么日转千街，凭着俺人力勇，弟兄多，便着他有非灾。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・采茶歌","p":"","d":"元代","a":"无名氏","c":["父亲你走将来快安排，今日个洛阳花酒一时来。", "(赵匡义云)姐姐，那韩松若知道呵，必然与俺争竞也。", "(正旦云)不怕他。", "(唱)统领军卒驱士马，我着他闻咱名姓命先衰。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・煞","p":"","d":"元代","a":"无名氏","c":["心中愁闷当时解，参透韩松大会垓。", "兄弟你今朝且耽待。", "我忙回住宅，自有个计划。", "便着你花烛筵开会宾客。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・中吕/粉蝶儿","p":"","d":"元代","a":"无名氏","c":["一会家心下念想，这姻缘怎生主张？我在那绣房中自在参详。", "(梅香云)姐姐，你则拣着好姐夫嫁了便罢也。", "(正旦云)你那里知道也。", "(唱)我须知你主意，则着我别寻投向。", "(梅香云)姐姐，你便想我那姐夫，不知我那姐夫想你也不想你也，(正旦唱)你这个无礼的梅香，你将我假支吾故来抵当。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・迎仙客","p":"","d":"元代","a":"无名氏","c":["父亲你听拜禀，诉衷肠，这亲礼两家儿两家儿可便那下里强？(王朴云)小姐，你则心顺的便成也。", "(正旦唱)我若是肯依随，休要讲，主张在尊堂。", "(夫人云)你休要这般说，我自有个主意也。", "(正旦唱)母亲你便有主张休谦让。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・红绣鞋","p":"","d":"元代","a":"无名氏","c":["狠媒证人前闲强，你着我嫁韩松罗锦千箱，我则待布袄荆钗守寒窗。", "(媒婆云)他家那饮馔也用不了。", "(正旦唱)便做道珍羞百味，干使碎你那好心肠。", "(媒婆云)你可嫁也不嫁？(正旦唱)劝你这强媒人休再往。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・上小楼","p":"","d":"元代","a":"无名氏","c":["他正那人前闹嚷，指望待成亲名望。", "看不上他-来一往，施展衣服，卖弄轻狂。", "(梅香云)小姐，你则丢下那绣球儿去来罢。", "(正旦唱)你着我将绣球儿，忙掷下，韩松身上，可不教那有情人每朝指望。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・幺篇","p":"","d":"元代","a":"无名氏","c":["他那里慢慢的来，我这里暗暗的慌。", "羞的我不敢抬头，连忙遮面，无处潜藏。", "(梅香云)绣球儿在这里，丢下去罢。", "(正旦唱)一见了绣球儿，心中悒怏，我着他霎时间共同鸳帐。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・般涉调耍孩儿","p":"","d":"元代","a":"无名氏","c":["我这里可咛觑了他模样，办着片志诚心便央。", "我则见军民士户在楼前，唬的我不敢名扬。", "(梅香云)姐姐丢下去罢。", "(正旦唱)我待要时间抛掷心中惧，又则怕错了教他向那厢。", "(梅香云)姐姐，你则望着我这赵姐夫抛了罢。", "(正旦唱)你也有心偏向，我将这绣球儿抛下。", "准备着齐整的陪房。", "(正旦云)我望着这赵匡义身上丢下去。", "(做抛下绣球科，赵匡义做接了科，韩松做夺了绣球科，云)是我的，你将的那里去？两个兄弟，俺得了绣球儿也，俺回家去来。", "(同胡缠歪缠下)(郑恩云)这厮好无礼也。", "是你的绣球儿，他夺的去了，更待干罢。", "俺打这厮去来。", "(符彦卿云)赵匡义，你休赶他去，我见绣球儿已是你的，你明日拣好日辰来娶，休要致怨。", "小姐，你下楼来，先回去罢。", "(正旦同做下楼科，云做见科，下)(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・煞尾","p":"","d":"元代","a":"无名氏","c":["到今日趁了心，绣球儿有忖量，至来朝约定同鸳帐，成就了一世儿夫妻慢慢的赏。", "(同梅香下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・仙吕/赏花时","p":"","d":"元代","a":"无名氏","c":["今日个婚姻才定准，亏了英雄十数人。", "(郑恩云)姐姐，若不是此计，怎生瞒过他也。", "(正旦唱)我若是半霎儿到家门，端的是机谋可便敬谨。", "(云)你见了俺父母呵。", "(唱)也少不的排佳宴，可兀的庆新婚。", "(同梅香下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・双调/新水令","p":"","d":"元代","a":"无名氏","c":["我虽是洞房无用的女妖娆，不错了圣人之道，夫妻是正理，休信外人教。", "不负了夜月花朝，当日个彩楼上众人闹。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・沈醉东风","p":"","d":"元代","a":"无名氏","c":["则听的聒耳笙歌闹吵，珍羞端的奇标。", "新婚今日成，受了那我少闲焦燥，谢神天保护的便坚牢。", "(符彦卿云)多亏了妙计，今日才得成就也。", "(正旦唱)今日个夫妇团圆成就好。", "(郑恩云)小姐，这一场也多亏了我也。", "(正旦唱)多谢你个仁兄智巧。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・雁儿落","p":"","d":"元代","a":"无名氏","c":["情理这韩松使燥暴、脑背后都来到。", "俺这里郑恩暗暗的藏，他那里不在声高高的闹。", "(赵弘殷云)他临后怎么去了来？(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・得胜令","p":"","d":"元代","a":"无名氏","c":["呀，打的是无处乱奔逃，那其间怒气怎生消。", "才得今朝定，则他这将军个个劳。", "(符彦卿云)既亏了郑恩，俺慢慢的谢他也。", "(正旦唱)父亲你量度，便把他恩临报。", "郑恩你休焦，今日个婚姻已定了。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・沽美酒","p":"","d":"元代","a":"无名氏","c":["父亲你休动劳，你孩儿正当报，则因那养育三年将我这性命保。", "指望终身待老，别离事在今朝。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赵匡义智娶符金锭・太平令","p":"","d":"元代","a":"无名氏","c":["多亏你个恩人说道，将亲事不错分毫。", "都则为韩松暴虐，将平人姻缘打落。", "(赵匡义云)夫妻皆是前定，岂他人能破的也呵。", "(正旦唱)呀，我这里说着，念着，笑倒，险些儿无着无落。", "(王朴云)今日个天下喜事，夫妻团圆。", "听我与您下断：您本是柴世忠良，一个个胆量高强。", "则因为赏春之景，来到你符氏门墙。", "赵匡义花下闲走，正见您年小红妆。", "既结下目前姻眷，搭彩楼招做新郎。", "有韩松依权挟势，遣官媒故意商量。", "恼犯了郑恩兄弟，施手段显耀刚强。", "诈妆做青春妇女，韩松见魂魄皆亡。", "今日个已成婚配，开筵会酒泛肴觞。", "赵匡义文武兼济，符金锭本性温良。", "今日个夫妻完备，一齐的拜谢吾皇。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"正宫・鹦鹉曲","p":"","d":"元代","a":"冯子振","c":["序云：白无咎有〔鹦鹉曲〕云：“侬家鹦鹉洲边住，是个不识字渔父。", "浪花中一叶扁舟，睡煞江南烟雨。", "觉来时满眼青山，抖擞绿蓑归去。", "算从前错怨天公，甚也有安排我处。", "”余壬寅岁留上京，有北京伶妇御园秀之属，相从风雪中，恨此曲无续之者。", "且谓前后多亲炙士大夫，拘于韵度，如第一个“父”字，便难下语；又“甚也有安排我处”，“甚”字必须去声字，“我”字必须上声字，音律始谐，不然不可歌，此一节又难下语。", "诸公举酒，索余和之，以汴、吴、上都、天京风景试续之。", "山亭逸兴嵯峨峰顶移家住，是个不唧溜樵父。", "烂柯时树老无花，叶叶枝枝风雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・故人曾唤我归来，却道不如休去。指门前万叠云山，是不费青蚨买处。荣华短梦","p":"","d":"元代","a":"冯子振","c":["幺朱门空宅无人住，村院快活煞耕父。", "霎时间富贵虚花，落叶西风残雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・总不如水北相逢，一棹木兰舟去。待霜前雪后梅开，傍几曲寒潭浅处。愚翁放浪","p":"","d":"元代","a":"冯子振","c":["幺东家西舍随缘住，是个忒老实愚父。", "赏花时暖薄寒轻，彻夜无风无雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・占长红小白园亭，烂醉不教人去。笑长安利锁名缰，定没个身心稳处。农夫渴雨","p":"","d":"元代","a":"冯子振","c":["幺年年牛背扶犁住，近日最懊恼杀农父。", "稻苗肥恰待抽花，渴煞青天雷雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・恨残霞不近人情，截断玉虹南去。望人间三尺甘霖，看一片闲云起处。燕南百五","p":"","d":"元代","a":"冯子振","c":["东风留得轻寒住，百五闹蝶母峰父。", "好花枝半出墙头，几点清明微雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・绣弯弯湿透罗鞋，绮陌踏青回去。约明朝后日重来，靠浅紫深红暖处。故园归计","p":"","d":"元代","a":"冯子振","c":["幺重来京国多时住，恰做了白发伧父。", "十年枕上家山，负我湘烟潇雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・","p":"","d":"元代","a":"冯子振","c":["断回肠一首阳关，早晚马头南去。", "对吴山结个茅庵，画不尽西湖巧处。", "野渡新晴孤村三两人家住，终日对野叟田父。", "说今朝绿水平桥，昨日溪南新雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・碧天边云归岩穴，白鹭一行飞去。便芒鞋竹杖行春，问底是青帘舞处。渔父","p":"","d":"元代","a":"冯子振","c":["幺沙鸥滩鹭衤离依住，镇日坐钓叟纶父。", "趁斜阳晒网收竿，又是南风催雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・绿杨堤忘系孤桩，白浪打将船去。想明朝月落潮平，在掩映芦花浅处。市朝归兴","p":"","d":"元代","a":"冯子振","c":["山林朝市都曾住，忠孝两字报君父。", "利名场反覆如云，又要商量阴雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・便天公有眼难开，袖手不如家去。更蛾眉强学时妆，是老子平生懒处。陆羽风流","p":"","d":"元代","a":"冯子振","c":["幺儿啼漂向波心住，舍得陆羽唤谁父？杜司空席上从容，点出茶瓯花雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・散蓬莱两腋清风，未便玉川仙去。待中泠一滴分时，看满注黄金鼎处。顾渚紫笋","p":"","d":"元代","a":"冯子振","c":["幺春风阳羡微喧住，顾渚问苕叟吴父。", "一枪旗紫笋灵芽，摘得和烟和雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・焙香时碾落云飞，纸上凤鸾衔去。玉皇前宝鼎亲尝，味恰到才情写处。园父","p":"","d":"元代","a":"冯子振","c":["幺柴门鸡犬山前住，笑语听伛背园父。", "辘轳边抱瓮浇畦，点点阳春膏雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・菜花间蝶也飞来，又趁暖风双去。杏梢红韭嫩泉香，是老瓦盆边饮处。野客","p":"","d":"元代","a":"冯子振","c":["幺春归不恋风光住，向老拙问讯槎父。", "叹匡山李白漂零，寂寞长安花雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・指沧溟铁网珊瑚，袖卷钓竿西去。锦袍空醉墨淋漓，是万古声名响处。城南秋思","p":"","d":"元代","a":"冯子振","c":["幺新凉时节城南住，灯火诵鲁国尼父。", "到秋来宋玉生悲，不赋高唐云雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・一声声只在芭蕉，断送别离人去。甚河桥柳树全疏，恨正在长亭短处。赤壁怀古","p":"","d":"元代","a":"冯子振","c":["幺茅庐诸葛亲曾住，早赚出抱膝梁父。", "笑谈间汉鼎三分，不记得南阳耕雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・叹西风卷尽豪华，往事大江东去。彻如今话说渔樵，算也是英雄了处。处士虚名","p":"","d":"元代","a":"冯子振","c":["高人谁恋朝中住，自古便有个巢父。", "子陵滩钓得虚名，几度桐江春雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・睡神仙别有陈抟，拂袖华山归去。漫纷纷少室终南，怎不是神仙隐处？洞庭钓客","p":"","d":"元代","a":"冯子振","c":["幺年光流水何曾住，早忘却姓吕岩父。", "记蓬莱阆苑相逢，一别风流如雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・算人间碧海桑田，只似燕鸿来去。岳阳楼剑气凌云，度老树神仙此处。黄阁清风","p":"","d":"元代","a":"冯子振","c":["幺箕尾傅说商岩住，空桑子伊尹无父。", "汉萧何昴宿分英，李靖唐时行雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・出山来济了苍生，却卷白云闲去。一千年黄阁清风，是万古声名响处。夷门怀古","p":"","d":"元代","a":"冯子振","c":["幺人生只合梁园住，快活煞几个白头父。", "指他家五辈风流，睡足胭脂坡雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・说宣和锦片繁华，辇路看元宵去。马行街直转州桥，相国寺灯楼几处。都门感旧","p":"","d":"元代","a":"冯子振","c":["都门花月蹉跎住，恰做了白发伧父。", "酒微醒曲榭回廊，忘却天街酥雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・夏侯瞒智肖杨修，强说不多来去。怕文章泄漏风光，谜语到难开口处。兰亭手卷","p":"","d":"元代","a":"冯子振","c":["幺兰亭不肯昭陵住，老逸少是献之父。", "过江来定武残碑，剥落元刂烟剜雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・纵新新茧纸临摹，乐事赏心俱去。永和年小草斜行，到野鹜家鸡窘处。庞隐图","p":"","d":"元代","a":"冯子振","c":["团栾话里禅龛住，灵昭女对老庞父。", "利名心不挂丝毫，更肯沾风粘雨？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・叹黄金散尽还家，逝水看流年去。只寻常卖簟篱休，这眷属今无讨处。拔宅冲升图","p":"","d":"元代","a":"冯子振","c":["幺淮南仙客蓬莱住，发漆黑变寻髯父。", "八公山九转丹成，洗尽腥风咸雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・想云霄犬吠鸡鸣，拔宅向青霄去。劝长安热客回头，镜影到流年老处。忆西湖","p":"","d":"元代","a":"冯子振","c":["幺吴侬生长西湖住，舣画舫听棹歌父。", "苏堤万柳春残，曲院风荷番雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・","p":"","d":"元代","a":"冯子振","c":["草萋萋一道腰裙，软绿断桥斜去。", "判兴亡说向林逋，醉梅屋梅梢偃处。", "感事黄金难买朱颜住，驷马客羡跨牛父。", "石将军百斛明珠，几日欢云娱雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・趁春归一瞬流莺，万事夕阳西去。旧婵娟落在谁家？个里是高人省处。赠园父","p":"","d":"元代","a":"冯子振","c":["幺春光浓艳城南住，一叶价百倍园父。", "牡丹台国色天香，锦幄无风无雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・惜花人不惜千金，一任蝶来蜂去。酒醒时月上三竿，是不是鸡声管处。感事","p":"","d":"元代","a":"冯子振","c":["幺江湖难比山林住，种果父胜刺船父。", "看春花又看秋花，不管颠风狂雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・尽人间白浪滔天，我自醉歌眠去。到中流手脚忙时，则靠着柴扉深处。买臣负薪手卷","p":"","d":"元代","a":"冯子振","c":["幺赭肩腰斧登山住，耐得苦是采薪父。", "乱云升急澍飞来，拗青松遮风雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・记年时雪断溪桥，脱度前湾归去。买臣妻富贵休休，气焰到寒灰舞处。燕南八景","p":"","d":"元代","a":"冯子振","c":["幺芦沟清绝霜晨住，步落月问倚阑父。", "蓟门东直下金台，仰看楼台飞雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・道陵前夕照苍茫，叠翠望居庸去。玉泉边一派西山，太液畔秋风紧处。松林","p":"","d":"元代","a":"冯子振","c":["幺山围行殿周遭住，万里客看牧羊父。", "听神榆树北车声，满载松林寒雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・应昌南旧日长城，带取上京愁去。又秋风落雁归鸿，怎说到无言语处。至上京","p":"","d":"元代","a":"冯子振","c":["幺澶河西北征鞍住，古道上不见耕父。", "白茫茫细草平沙，日日金莲川雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・李陵台往事休休，万里汉长城去。趁燕南落叶归来，怕迤<辶里>飞狐冷处。忆鸡鸣山旧游","p":"","d":"元代","a":"冯子振","c":["幺鸡鸣山下荒丘住，客吊古问驿亭父。", "几何年野屋丛祠，灭没犁烟锄雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・默寻思半晌无言，逆旅又催人去。指峰前代妤磨笄，是血泪当时洒处。南城赠丹砂道伴","p":"","d":"元代","a":"冯子振","c":["幺长松苍鹤相依住，骨老健称褐衣父。", "坐烧丹忘记春秋，自在溪风山雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・有人来不问亲疏，淡饭一杯茶去。要茅檐卧看闲云，梅影转幽窗雅处。别意","p":"","d":"元代","a":"冯子振","c":["幺花骢嘶断留侬住，满酌酒劝据鞍父。", "柳青青万里初程，点染阳关朝雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・梦回时不见犀梳，燕子又衔春去。便人间月缺花残，是小小香魂断处。","p":"","d":"元代","a":"冯子振","c":["溪山小景长绳短系虚名住，倾浊酒劝邻父。", "草亭前矮树当门，画出轻烟疏雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・","p":"","d":"元代","a":"冯子振","c":["看燕南陌上红尘，马耳北风吹去。", "一年年月夜花朝，自占取溪山好处。", "四皓屏张良更姓圯桥住，夜待旦遇个师父。", "一编书不为封留，字字咸阳膏雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"・借箸筹灭项兴刘，到底学神仙去。待商山四皓还山，再不恋人间险处。","p":"","d":"元代","a":"冯子振","c":["幺逃吴辞楚无家住，解宝剑赠津父。", "十年间隶越鞭荆，怒卷秋江潮雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・","p":"","d":"元代","a":"冯子振","c":["想空城组练三千，白马素车回去。", "又逡巡月上波平，暮色在烟光紫处。", "青衫司马江州住，月夜笛厌听村父。", "甚有传旧谱琵琶，切切嘈嘈檐雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"中吕・红绣鞋题小山苏堤渔唱","p":"","d":"元代","a":"冯子振","c":["东里先生酒兴，南州高士文声，玉龙嘶断彩鸾鸣。", "水空秋月冷，山小暮天青，苏公堤上景。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・意无聊，愁无限，花落也莺慵燕懒。两地相思会面难，上危楼凭暖雕","p":"","d":"元代","a":"高安道","c":["畅心烦，盼杀人也秋水春山！几时看宝髻蓬松云乱绾？怕的是樽空酒阑，月斜人散，背银灯偷把泪珠弹。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"般涉调・哨遍嗓淡行院","p":"","d":"元代","a":"高安道","c":["暖日和风清昼，茶馀饭饱斋时候。", "自汉抱官囚，被名缰牵挽无休。", "寻故友，出来的衣冠济楚，像儿端严，一个个特清秀，都向门前等候。", "待去歌楼作乐，散闷消愁。", "倦游柳陌恋烟花，且向棚阑玩俳优。", "赏一会妙舞清歌，瞅一会皓齿明眸，躲一会闲茶浪酒。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"耍孩儿・诧跋的单脚实村纣，呼喝的扌且扌来每叫吼。瞅粘的绿老更昏花，","p":"","d":"元代","a":"高安道","c":["把棚的莽壮真牛。", "吹笛的把瑟歪着尖嘴，擂鼓的撅丁瘤着左手，撩打的腔腔嗽。", "靠棚头的先虾着脊背，卖薄荷的自肿了咽喉。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"七煞・坐排场众女流，乐床上似兽头，栾睃来报是些十分丑。一个个青布","p":"","d":"元代","a":"高安道","c":["裙紧紧的兜着奄老，皂纱片深深的裹着额楼。", "棚上下把郎君溜，喝破子把腔儿莽诞，打讹的将纳老胡风彡。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"六・撺断的昏撒多，主张的自吸溜，几曾见双撮泥金袖。可怜虱虮沿肩甲，","p":"","d":"元代","a":"高安道","c":["犹道珍珠络臂耩。", "四翩儿乔弯纽，甚实曾官梅点额，谁肯将蜀锦缠头。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"三・妆旦不抹风彡，蠢身躯似水牛，嗓暴如恰哑了孤桩狗。带冠梳硬挺着","p":"","d":"元代","a":"高安道","c":["粗脖项，恰掌记光舒着黑指头。", "肋额的相迤逗，写着道翩跹舞态，宛转歌喉。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"一・打散的队子排，待将回数收，搽灰抹土胡亻孱亻愁。淡翻东瓦来西瓦，","p":"","d":"元代","a":"高安道","c":["却甚放走南州共北州。", "凹了也难收救，四边厢土糁，八下里砖风彡。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・梁园中可惯经，桑园里串的熟。似兀的武光头、刘色长、曹娥秀，则","p":"","d":"元代","a":"高安道","c":["索赶科地沿村转疃走。", "皮匠说谎十载寒窗诚意，书生皆想登科记。", "奈时运未亨通，混尘嚣日日衔杯，厮伴着青云益友。", "谈笔忘机，出语无俗气。", "偶题起老成靴脚，人人道好，个个称奇。", "若要做四缝磕瓜头，除是南街小王皮。", "快做能裁，着脚中穿，在城第一。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"七煞・探头休蹴尖，衬薄怕汗湿。减刮的休显刀痕迹，剜裁的脸戏儿微分","p":"","d":"元代","a":"高安道","c":["间短，拢揎得腮帮儿省可里肥。", "要着脚随人意，休教脑窄，莫得趺低。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"六・丁宁说了一回，分明听了半日，交付与价钞先伶俐。从前名誉休多说，","p":"","d":"元代","a":"高安道","c":["今后生活便得知。", "限三日穿新的，您休说谎，俺不催逼。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"四・几番煨胶锅借揎头，数遍粘主根买桦皮，喷了水埋在糠糟内。今朝取","p":"","d":"元代","a":"高安道","c":["了明朝取，早又催来晚又催。", "怕越了靴行例，见天阴道胶水解散，恰天晴说皮糙ㄡ黧。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"三・走的来不发心，ㄡ的方见次第，计数儿算有三千个誓。迷奚着谎眼先","p":"","d":"元代","a":"高安道","c":["陪笑，执闭着顽心更道易。", "巴的今日，罗街拽巷，唱叫扬疾。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"二・好一场恶一场，哭不得笑不得，软厮禁硬厮拼却不济。调脱空对众攀","p":"","d":"元代","a":"高安道","c":["今古，念条款依然说是非。", "难回避，骷髅卦几番自说，猫狗砌数遍亲题。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"一・又不是凤麒麟钩绊着缝，又不是鹿衔花窟嵌着刺，又不是倒钩针背衬","p":"","d":"元代","a":"高安道","c":["上加些功绩，又不是三垂云银线分花样，又不是一抹圈金沿宝里。", "每日闲淘气，子索行监坐守，谁敢东走西移。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・初言定正月终，调发到十月一。新靴子投至能够完备，旧兀刺先磨了","p":"","d":"元代","a":"高安道","c":["半截底。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・混江龙","p":"","d":"元代","a":"马致远","c":["当日个曾逢关尹，至今遗下五千文。", "大刚来玄虚为本，清净为门。", "虽然是草舍茅庵一道士，伴着这清风明月两闲人。", "也不知甚的秋，甚的春，甚的汉，甚的秦，长则是习疏狂、躯懒散、佯妆钝，把些个人间富贵，都做了眼底浮云。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・油葫芦","p":"","d":"元代","a":"马致远","c":["莫厌追欢笑语频，但开怀好会宾，寻思离乱可伤神。", "俺闲遥遥独自林泉隐，你虚飘飘半纸功名进。", "你看这紫塞军、黄阁臣，几时得个安闲分，怎如我物外自由身。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・天下乐","p":"","d":"元代","a":"马致远","c":["他每得到清平有几人，何不早抽身，出世尘，尽白云满溪锁洞门，将一函经手自翻，一垆香手自焚。", "这的是清闲真道本。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・金盏儿","p":"","d":"元代","a":"马致远","c":["上昆仑，摘星辰，觑东洋海则是一掬寒泉滚，泰山一捻细微尘。", "天高三二寸，地厚一鱼鳞，抬头天外觑，无我一般人。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・后庭花","p":"","d":"元代","a":"马致远","c":["我驱的是六丁六甲神，七星七曜君。", "食紫芝草千年寿，看碧桃花几度春。", "常则是醉醺醺、高谈阔论，来往的尽是天上人。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・醉中天","p":"","d":"元代","a":"马致远","c":["俺那里自泼村醪嫩，自折野花新。", "独对青山酒一尊，闲将那朱顶仙鹤引。", "醉归去松阴满身，冷然风韵，铁笛声吹断云根。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・金盏儿","p":"","d":"元代","a":"马致远","c":["俺那里地无尘，草长春，四时花发常娇嫩。", "更那翠屏般山色对柴门，雨滋棕叶润，露养药苗新。", "听野猿啼古树，看流水绕孤村。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・醉雁儿","p":"","d":"元代","a":"马致远","c":["你有那出世超凡神仙分，击一条一抹绦，带一顶九阳巾。", "君，敢着你做真人。", "(洞宾云)俺为官的，身穿锦缎轻纱，口食香甜美味。", "你出家人草履麻绦，餐松啖柏，有甚么好处？(正末云)功名二字，如同那百尺高竿上调把戏一般，性命不保，脱不得酒色财气这四般儿。", "笛悠悠，鼓冬冬，人闹吵，在虚空。", "怎如的平地上来，平地上去，无灾无祸，可不自在多哩。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・后庭花","p":"","d":"元代","a":"马致远","c":["酒恋清香疾病因，色爱荒淫患难根；财贪富贵伤残命，气竞刚强损隐身。", "这四件儿不饶人。", "你若是将他断尽，便神仙有几分。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・醉中天","p":"","d":"元代","a":"马致远","c":["假饶你手段欺韩信，舌辩赛苏秦，到底个功名由命不由人，也未必能拿准。", "只不如苦志修行谨慎，早图个灵丹腹孕，索强似你跨青驴踯躅风尘。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・一半儿","p":"","d":"元代","a":"马致远","c":["如今人宜假不宜真，则敬衣衫不敬人。", "题起修行耳怕闻，直恁的没精神，一半儿应承一半儿盹。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・金盏儿","p":"","d":"元代","a":"马致远","c":["比及你米淘了尘，水烧的滚，我教这一颗米内藏时运，半升铛里煮乾坤。", "投至得黄粱炊未熟，他清梦思犹昏，我教他江山重改换，日月一番新。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・赚煞","p":"","d":"元代","a":"马致远","c":["羽衣轻，霓旌迅，有十二金童接引。", "万里天风归路稳，向蓬莱顶上朝真。", "笑欣欣。", "袖拂白云，宴罢瑶池酒半醺。", "争奈你个唐吕岩性蠢，偏不肯受汉钟离教训，又则索跨苍鸾飞上九天门。", "(下)(洞宾梦上，云)兀那王婆，那先生去了也。", "(王婆云)去久了。", "(洞宾云)饭熟也未？(王婆云)还饶一把火儿。", "(洞宾云)王婆，我也等不的你那饭了，误了我程途。", "我上的蹇驴，便索长行去也。", "(下)(王婆云)吕岩去了也。", "他那里知道我非凡人，乃骊山老母一化。", "上仙法旨，着吕岩看破了酒色财气，人我是非，那其间才得返本朝元，重回正道。", "(诗云)汉钟离点化玄机，度吕岩省悟心回。", "待此人功成行满，同共赴阆苑瑶池。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・仙吕/赏花时","p":"","d":"元代","a":"马致远","c":["则我是皓首苍颜高太尉，别无甚亲人则觑着你。", "儿幼小女娇痴，想为人在世，最苦是生离。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・幺篇","p":"","d":"元代","a":"马致远","c":["满饮阳关酒一杯。", "(洞宾做吐科，云)您孩儿吃不得了，心中有些不好，吐了两口血。", "这酒元来伤人。", "您孩儿再也不吃这酒了。", "(高太尉云)既是伤着你心，再也休吃这酒罢。", "(洞宾云)父亲放心，您孩儿不吃了，辞别父亲，便索长行。", "(高太尉云)你休忘了我的言语，着心记者。", "(唱)则要你在意扶持唐社稷，嘱付了又重题。", "但愿的功成破敌，早唱凯歌回。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・醋葫芦","p":"","d":"元代","a":"马致远","c":["又不是别人相唬吓、厮展赖，是你男儿亲自撞将来。", "你浑身是口难分解，赤紧的并脏拿贼，你看他死临侵不敢把头抬。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・幺篇","p":"","d":"元代","a":"马致远","c":["你男儿有八面威，七步才，现带着征西金印虎头牌。", "他在那长朝殿前班部里摆。", "你教他把屎盆儿顶戴，兀的不屈沉杀了拜将筑坛台。", "(云)老汉有甚么面皮？大人，可怜见一双儿女，饶过夫人者。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・幺篇","p":"","d":"元代","a":"马致远","c":["大人见义为，夫人知过改。", "不是中间老汉厮支划，若是外人知道来，休恁的大惊小怪。", "丑名儿出去怎生揩！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・幺篇","p":"","d":"元代","a":"马致远","c":["问甚你夫妻好共歹，觑孩儿瘦更呆，便怎生教碜可可血泊里倘着尸骸？男子汉那一个不妒色。", "(带云)不争夫人死呵！(唱)枉乞两的两个小冤家不快，那凄凉日月索耽捱。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・幺篇","p":"","d":"元代","a":"马致远","c":["我见他掩了泪眼，改了面色，笑靥儿攒破旱莲腮，直从那针关儿透得命到来，恰便似九霄云外，滴溜溜飞下一纸赦书来。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・幺篇","p":"","d":"元代","a":"马致远","c":["朝廷将使命差，前厅上把圣旨开。", "道是西边上卖阵走回来。", "谁教你贪心爱他不义财。", "今日个脱空须败，恶支沙将这等罪名揣。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・幺篇","p":"","d":"元代","a":"马致远","c":["也是你慈悲生患害，俺哥哥除死无大灾。", "何须你畅叫厮花白。", "(旦儿云)我是高太尉女儿，养汉来，养汉来。", "如今你休了我，谁管的我？(正末唱)闹垓垓幺喝十字街。", "(带云)他今日声声说是高太尉女儿养汉来。", "(唱)直恁的恶叉白赖，婆娘家情性恁般乖。", "(解子云)去罢，误了程限到几时。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・后庭花","p":"","d":"元代","a":"马致远","c":["我则见飕飕的枷棒摔，打的他纷纷的皮肉开。", "见他可擦擦拖将去，我与你气丕丕赶上来。", "痛哀哉，身遭残害，他如何敢挣扎。", "我其实无百刂划，平白地招罪责，从今日离院宅。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・双雁儿","p":"","d":"元代","a":"马致远","c":["哥哥也恰如赵杲送灯台，便道不的。", "山河易改。", "恁时节和尚在钵盂在，今日个、福气衰，看何时、冤业解。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・随调煞","p":"","d":"元代","a":"马致远","c":["好教我回去艰难，谁似你步行的快。", "望不见。", "走上望高台，空目断一天残照霭。", "不知俺哥哥安在？(做叫科云)哥哥！(洞宾远应科)(正末唱)看时节隔疏林风送过哭声来。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・大石调/六国朝","p":"","d":"元代","a":"马致远","c":["风吹羊角，雪剪鹅毛，飞六出海山白，冻一壶天地老。", "便有丹青巧，画笔难描。", "俺这里遥望千山表，是谁将粉黛扫？幽窗下寒敲竹叶，前村里冷压梅梢。", "撩乱野云低，微茫江树杳。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・归塞北","p":"","d":"元代","a":"马致远","c":["为甚春归早，既不沙可怎生蝶翅舞飘飘？梅蕊粉填合长安道。", "柳花绵迷却灞陵桥。", "山馆酒旗遥。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・初问口","p":"","d":"元代","a":"马致远","c":["想那捕鱼叟蓑笠纶竿，他向那寒潭独钓，和俺这采樵人迷却归来道。", "则见冻雀又飞，寒鸦又噪，古木林中蓦听的山犭员叫。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・怨别离","p":"","d":"元代","a":"马致远","c":["园林无处不萧条，春归也犹未觉。", "满地梨花无人扫。", "寒料峭，遥望见一点青山，兀良、却又早不见了。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・归塞北","p":"","d":"元代","a":"马致远","c":["白云岛，则听得孤鬼吼荒郊。", "九天女鼓风驱造化，六丁神挥剑斩长蛟。", "既不沙，可怎生就地卷风涛。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・幺篇","p":"","d":"元代","a":"马致远","c":["孤村晓，稚子道犹自月明高。", "青女翦冰寒不散，黑云喷雨冻难消，无处觅渔樵。", "(洞宾云)孩儿行动些。", "如此大风大雪，又迷踪失路，眼见的是死人也。", "(做椎胸科，云)天口乐！这雪住一住可也好，越下的恶躁了。", "(正末云)这来的是吕岩，可也该省悟了。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・擂鼓体","p":"","d":"元代","a":"马致远","c":["那先生浩歌拍手舞黄鹤，家住瑶池阆苑，十洲三岛。", "一曲横笛秋气高，数着残棋江月晓。", "(洞宾云)哥哥，那先生是出家人，怎生有这本事？(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・归塞北","p":"","d":"元代","a":"马致远","c":["那先生服的是长生药，不许外人学。", "三弄琴声弹落叶，九重春色醉仙桃，白日上青霄。", "(洞宾云)敢问哥哥，那先生是怎生模样，你再说一遍咱。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・净瓶儿","p":"","d":"元代","a":"马致远","c":["那先生两手摇山岳，一对眼瞅邪妖。", "剑挥星斗，胸卷江涛。", "天教恶相貌，伏的虎，降的龙，德行高。", "他则是个活神道，也曾跨苍鸾亲把玉皇朝。", "(云)君子，你过的山崦儿，你望见团标，你问那先生路去。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・玉翼蝉煞","p":"","d":"元代","a":"马致远","c":["那先生自舞自歌，吃的是仙酒仙桃，住的是草舍茅庵，强如龙楼凤阁。", "白云不扫，苍松自老；青山围绕，淡烟笼罩。", "黄精自饱，灵丹自烧。", "崎岖峪道，凹答岩壑；门无绰楔，洞无销钥；香焚石桌，笛吹古调；云黯黯，水迢迢，风凛凛，雪飘飘，柴门静，竹篱牢。", "过了那峻岭尖峰，曲涧寒泉，长林茂草，便望见那幽雅仙庄，这些是道。", "(带云)君子，你休迷了正道。", "你听者，(唱)你可也休错去了。", "(下)(洞宾云)孩儿也，你才听的那哥哥说来，兀那山崦里有一家人家，吃的也有，穿的也有，宿处也有。", "咱直到那里觅一宵宿去来。", "(同下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・滚绣球","p":"","d":"元代","a":"马致远","c":["寻思来，那快活，这半月多遇几个滥官员经过，打动下些金银段匹绫罗。", "昨日共那几个，今日共这一火。", "从不曾离了侧坐，仰天的大笑呵呵。", "将那泼醅酒虢虢连糟咽，杀人剑蚩蚩带血磨。", "常则是烂醉无何。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・倘秀才","p":"","d":"元代","a":"马致远","c":["我为贼盗呵杀人放火，不似你贪财呵披枷带锁。", "你得了斗来大黄金印一颗，为元帅、佐山河，倒大来显豁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・滚绣球","p":"","d":"元代","a":"马致远","c":["你那罪过，怎过活，做的来实难结末，自揽下千丈风波。", "谁教你向界河，受财货，将咱大军折挫？似这等不义财贪得如何，道不的\"殷勤过日灾须少，侥幸成家祸必多\"，枉了张罗。", "(洞宾云)不好了，我不问那里逃命去来。", "(正末仗剑赶洞宾。", "躲科)(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・倘秀才","p":"","d":"元代","a":"马致远","c":["你早则省得浮世风灯石火，再休恋儿女神珠玉颗。", "咱人百岁光阴有几何，端的日月去、似撺梭。", "想你那受过的坎坷。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"邯郸道省悟黄粱梦・煞尾","p":"","d":"元代","a":"马致远","c":["你正果正是修行果，你灾咎皆因我度脱。", "早则绝忧愁、没恼聒，行处行，坐处坐，闲处闲，陀处陀。", "屈着指，自数过，真神仙，是七座，添伊家，总八个。", "道与哥哥，非是风魔，这个爱吃酒的钟离便是我。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"仙吕・后庭花拟古","p":"","d":"元代","a":"邵亨贞","c":["铜壶更漏残，红汝春梦阑。", "江上花无语，天涯人未还。", "倚楼闲，月明千里，隔江何处山？刺船鹦鹉洲，题诗黄鹤楼。", "金谷铜驼梦，湘云楚水愁。", "少年游，好怀依旧，故人还在不？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"越调・凭阑人题曹云西翁赠妓小画","p":"","d":"元代","a":"邵亨贞","c":["谁写江南一段秋，妆点钱塘苏小楼？楼中多少愁！楚山无断头。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"}
];